950		public CalculatedTimeline selectFinalTimeline(String funcName, List<CalculatedTimeline> timelines) {
951			if ("最早".equals(funcName)) {
952				return timelines.stream().min(Comparator.comparing(CalculatedTimeline::getExpectTime, Comparator.nullsLast(Comparator.naturalOrder()))
