433	    public List<EventNode> getDataNodeList(List<EventNode> fugureNodeList, Map<String, List<IndicatorOrder>> orderMap,
434	                                           Map<String, List<IndicatorProjectOrder>> projectOrderMap) {
435	        // 获取全部需要拉取轨迹的node
436	        Set<EventNode> dataNodeSet = new HashSet<>();
437	        for (EventNode node : fugureNodeList) {
438	
439	            // 尝试按照orderNo过滤数据, 注意不要修改orderMap
440	            List<IndicatorOrder> orders = new ArrayList<>(orderMap.getOrDefault(node.getCategoryId(), new ArrayList<>()));
441	
442	            // 如果是下单节点, 需要特殊处理, 使用projectOrder
443	            List<IndicatorProjectOrder> projectOrders = node.getName().equals("下单") ? projectOrderMap.getOrDefault(node.getCategoryId(), new ArrayList<>()) : new ArrayList<>();
444	
445	            for (NodeEdge edge : node.getEdgeInList()) {
446	                if (hasFilterRules(edge.getRuleList(), orders, projectOrders)) {
447	                    dataNodeSet.add(edge.getNodeFrom());
448	                    // 验证通过的话, figureNode自身也需要获取时间
449	                    // 因为实际完成时间需要写到考核结果中
450	                    dataNodeSet.add(node);
451	                }
452	            }
453	        }
454	        return new ArrayList<>(dataNodeSet);
455	    }
