633	    public List<NodeTimeTrackV2> getScheduleTimeTrack(String projectOrderId, ScheduleAllNode scheduleAllNode, List<ScheduleEventNode> dataNodeList) {
634	        List<NodeTimeTrackV2> res = new ArrayList<>();
635	        if (CollectionUtils.isEmpty(dataNodeList)) {
636	            return res;
637	        }
638	
639	        // 获取品类对应的orderNos
640	        Map<String, List<String>> categoryOrderNoMap = new HashMap<>();
641	        for (Map.Entry<Long, IndicatorOrder> entry : scheduleAllNode.getOrderMap().entrySet()) {
642	            IndicatorOrder order = entry.getValue();
643	            if (!categoryOrderNoMap.containsKey(order.getCategoryId())) {
644	                categoryOrderNoMap.put(order.getCategoryId(), new ArrayList<>());
645	            }
646	            categoryOrderNoMap.get(order.getCategoryId()).add(order.getOrderNo());
647	        }
648	
649	        Map<Integer, List<ScheduleEventNode>> eventTypeMap = dataNodeList.stream()
650	                .collect(Collectors.groupingBy(ScheduleEventNode::getEventType));
651	
652	        // 构建数据源
653	        BaseDataContext dataContext = buildScheduleTimeDataContext(projectOrderId, categoryOrderNoMap, eventTypeMap);
654	        scheduleAllNode.setBaseDataContext(dataContext);
655	
656	        // 为任务载体赋值任务耗时
657	        List<IndicatorBaseEvent> allBaseEvents = indicatorScheduleDAGService.getAllBaseEvents();
658	        Map<String, String> scheduleCodeToName = allBaseEvents.stream()
659	                .collect(Collectors.toMap(IndicatorBaseEvent::getScheduleCode, IndicatorBaseEvent::getEventName, (v1, v2) -> v1));
660	
661	        // 初始化各载体的任务耗时
662	        // 为特殊任务载体设置relateNodeId
663	        initInnerIntervalAndRelateNodeId(scheduleAllNode, scheduleCodeToName, dataContext.getTasks());
664	        LOGGER.info("getScheduleTimeTrac初始化任务载体的任务耗时和relateNodeId完成: {}", JsonUtil.obj2JsonStr(scheduleAllNode));
665	
666	        for (ScheduleEventNode eventNode : dataNodeList) {
667	            TimeExtractor extractor = timeExtractorFactory.findExtractor(EventTypeEnum.getEnumByValue(eventNode.getEventType()));
668	            List<NodeTimeTrackV2> timeTrackList = extractor.getScheduleTimeTrack(eventNode, dataContext, categoryOrderNoMap);
669	            res.addAll(timeTrackList);
670	        }
671	
672	        res.forEach(nodeTimeTrackV2 -> {
673	            List<NodeTimeTrackV2.TimeInfo> timeInfos = nodeTimeTrackV2.getTimeInfos();
674	            timeInfos.forEach(t -> {
675	                t.setAssessmentTime(DateUtil.filterInvalidDate(t.getAssessmentTime()));
676	                t.setCompleteTime(DateUtil.filterInvalidDate(t.getCompleteTime()));
677	            });
678	            timeInfos.removeIf(t -> t.getAssessmentTime() == null && t.getCompleteTime() == null);
679	        });
680	
681	        LOGGER.info("getScheduleTimeTrac轨迹数据构建完成: {}", JsonUtil.obj2JsonStr(res));
682	        return res;
683	    }
