286	    public ScheduleDAG getScheduleDAG(String projectOrderId) throws RpcException {
287	        ScheduleDAG res = null;
288	        Long version = constructionScheduleRpcService.getIndicatorVersion(projectOrderId);
289	        if (version == null) {
290	            LOGGER.info("无法构建考核DAG, projectOrderId={} 未配置排程规则", projectOrderId);
291	            return res;
292	        }
293	        String cacheString = SCHEDULE_DAG_CACHE.getIfPresent(version.toString());
294	        res = StringUtils.isBlank(cacheString) ? rebuild(version) : JsonUtil.jsonStr2Obj(cacheString, ScheduleDAG.class);
295	        res.setScheduleEdgeMap(new HashMap<>());
296	        res.setScheduleNodeMap(res.getScheduleEventNodes().stream()
297	                .collect(Collectors.toMap(ScheduleEventNode::getUniqCode, e -> e)));
298	
299	        // 因为深拷贝的原因, 引用类数据需要重新赋值
300	        // 初始化edgeMap
301	        for (ScheduleEdgeRule edgeRule : res.getScheduleEdgeRules()) {
302	            for (String codeFrom : edgeRule.getCodeFromList()) {
303	                String codeTo = edgeRule.getCodeTo();
304	                ScheduleEventNode nodeFrom = res.getScheduleNodeMap().get(codeFrom);
305	                ScheduleEventNode nodeTo = res.getScheduleNodeMap().get(codeTo);
306	                if (nodeFrom == null || nodeTo == null) {
307	                    LOGGER.info("scheduleDAG中未找到对应的节点, codeFrom: {}, codeTo: {}", codeFrom, codeTo);
308	                    continue;
309	                }
310	                String edgeKey = codeFrom + "," + codeTo;
311	                if (!res.getScheduleEdgeMap().containsKey(edgeKey)) {
312	                    ScheduleNodeEdge nodeEdge = ScheduleNodeEdge.builder()
313	                            .nodeFrom(nodeFrom)
314	                            .nodeTo(nodeTo)
315	                            .ruleList(new ArrayList<>())
316	                            .build();
317	                    res.getScheduleEdgeMap().put(edgeKey, nodeEdge);
318	
319	                    // 设置入度出度
320	                    nodeFrom.getEdgeOutList().add(nodeEdge);
321	                    nodeTo.getEdgeInList().add(nodeEdge);
322	                }
323	                res.getScheduleEdgeMap().get(edgeKey).getRuleList().add(edgeRule);
324	            }
325	        }
326	
327	        // 初始化nodeMap, 将入度出度为0的节点过滤掉
328	        res.setScheduleEventNodes(res.getScheduleEventNodes().stream()
329	                .filter(en -> !(en.getEdgeOutList().isEmpty() && en.getEdgeInList().isEmpty()))
330	                .collect(Collectors.toList()));
331	        res.setScheduleNodeMap(res.getScheduleEventNodes().stream()
332	                .collect(Collectors.toMap(ScheduleEventNode::getUniqCode, e -> e)));
333	        LOGGER.info("创建排程DAG成功, eventNodes: {}, edgeRules: {}", res.getScheduleEventNodes().size(), res.getScheduleEdgeRules().size());
334	        return res;
335	    }
