337	    public ScheduleDAG rebuild(Long version) throws RpcException {
338	        LOGGER.info("构建排程考核DAG, 版本: {}", version);
339	
340	        // 1.0 基础数据准备
341	        // 基础事件
342	        List<IndicatorBaseEvent> allBaseEvents = getAllBaseEvents();
343	
344	        // 材料排程考核规则
345	        List<ProcessNodeCfgDTO> processNodeCfgList = constructionScheduleService.getIndicatorRules(version);
346	        processNodeCfgList = processNodeCfgList.stream()
347	                .filter(cfg -> StringUtils.isNotEmpty(cfg.getMaterialCode()))
348	                .collect(Collectors.toList());
349	        LOGGER.info("scheduleRebuild基础数据准备完成");
350	
351	        // 2.0 将基础数据整理成DAG结构
352	        // 材料, 基装包映射
353	        // 材料可以出现在a -> b中的任意一端, 基装包只会出现在a端
354	        Map<String, String> categoryMap = new HashMap<>();
355	        categoryMap.putAll(processNodeCfgList.stream()
356	                .collect(Collectors.toMap(ProcessNodeCfgDTO::getMaterialCode, ProcessNodeCfgDTO::getMaterialName, (v1, v2) -> v1)));
357	        for (ProcessNodeCfgDTO cfg : processNodeCfgList) {
358	            for (NodeAssessmentRuleCfgDTO ruleCfg : cfg.getNodeAssessmentRuleCfgList()) {
359	                if (StringUtils.isNotEmpty(ruleCfg.getRelationMaterialCode())) {
360	                    categoryMap.put(ruleCfg.getRelationMaterialCode(), ruleCfg.getRelationMaterialName());
361	                }
362	            }
363	        }
364	
365	        // 排程code向ofcCode的映射， 不包含品类信息
366	        Map<String, String> uniqCodeToName = new HashMap<>();
367	        Map<String, String> scheduleCodeToCode = new HashMap<>();
368	
369	        // 初始化工期事件
370	        List<ScheduleEventNode> scheduleEventNodes = allBaseEvents.stream()
371	                .filter(event -> EventTypeEnum.CONSTRUCTION_SCHEDULE.getValue().equals(event.getEventType()))
372	                .map(event -> ScheduleEventNode.builder()
373	                        .uniqCode(event.getCode())
374	                        .name(event.getEventName())
375	                        .ofcCode(event.getCode())
376	                        .scheduleCode(event.getScheduleCode())
377	                        .categoryId("")
378	                        .categoryName("")
379	                        .eventType(event.getEventType())
380	                        .timeType(event.getTimeType())
381	                        .taskInfo(event.getTaskInfo())
382	                        .edgeInList(new ArrayList<>())
383	                        .edgeOutList(new ArrayList<>())
384	                        .build())
385	                .collect(Collectors.toList());
386	
387	        // 初始化品类事件(基装包事件也走此逻辑)
388	        for (String categoryId : categoryMap.keySet()) {
389	            String categoryName = categoryMap.get(categoryId);
390	            for (IndicatorBaseEvent event : allBaseEvents) {
391	                if (!EventTypeEnum.CONSTRUCTION_SCHEDULE.getValue().equals(event.getEventType())) {
392	                    ScheduleEventNode node = ScheduleEventNode.builder()
393	                            .uniqCode(categoryId + "_" + event.getCode())
394	                            .name(event.getEventName())
395	                            .ofcCode(event.getCode())
396	                            .scheduleCode(event.getScheduleCode())
397	                            .categoryId(categoryId)
398	                            .categoryName(categoryName)
399	                            .eventType(event.getEventType())
400	                            .timeType(event.getTimeType())
401	                            .taskInfo(event.getTaskInfo())
402	                            .edgeInList(new ArrayList<>())
403	                            .edgeOutList(new ArrayList<>())
404	                            .build();
405	                    scheduleEventNodes.add(node);
406	                    uniqCodeToName.put(node.getUniqCode(), node.getName());
407	                }
408	                scheduleCodeToCode.put(event.getScheduleCode(), event.getCode());
409	            }
410	        }
411	
412	        // {ruleId: {indexId: ScheduleEdgeRule, ...}}
413	        Map<String, Map<Integer, ScheduleEdgeRule>> scheduleEventRuleMap = new HashMap<>();
414	        for (ProcessNodeCfgDTO cfg : processNodeCfgList) {
415	            for (NodeAssessmentRuleCfgDTO ruleCfg : cfg.getNodeAssessmentRuleCfgList()) {
416	                String ruleId = getRuleId(cfg, ruleCfg);
417	                String codeFrom = convertNodeCode(ruleCfg.getRelationNodeCode(), ruleCfg.getRelationMaterialCode(), cfg.getTaskType(), scheduleCodeToCode);
418	                String codeTo = convertNodeCode(ruleCfg.getNodeCode(), ruleCfg.getMaterialCode(), cfg.getTaskType(), scheduleCodeToCode);
419	                if (!scheduleEventRuleMap.containsKey(ruleId)) {
420	                    scheduleEventRuleMap.put(ruleId, new HashMap<>());
421	                }
422	                if (!scheduleEventRuleMap.get(ruleId).containsKey(ruleCfg.getDivide())) {
423	                    boolean replenish = AssessRuleRestartTypeEnum.REBATE.getCode().equals(ruleCfg.getRestartType());
424	                    boolean restart = AssessRuleRestartTypeEnum.RESTART.getCode().equals(ruleCfg.getRestartType());
425	                    ScheduleEdgeRule edgeRule = ScheduleEdgeRule.builder()
426	                            .ruleId(ruleId)
427	                            .funcName(cfg.getValueRetrievalLogic().equals(0) || restart ? "最晚" : "最早")
428	                            .indexId(ruleCfg.getDivide())
429	                            .indicatorName(uniqCodeToName.get(codeTo))
430	                            .categoryId(cfg.getMaterialCode())
431	                            .categoryName(cfg.getMaterialName())
432	                            .deliveryId(cfg.getSupplierCode().equals("9999999") ? "-1" : cfg.getSupplierCode())
433	                            .deliveryType(cfg.getDeliveryType())
434	                            .restart(restart)
435	                            .replenish(replenish)
436	                            .codeFromList(new ArrayList<>())
437	                            .codeTo(codeTo)
438	                            .timeType(ruleCfg.getDurationType())
439	                            .timeRef(TIME_REF_MAP.getOrDefault(ruleCfg.getScheduleRelation(), ""))
440	                            .interval(new BigDecimal(ruleCfg.getDuration()))
441	                            .build();
442	                    scheduleEventRuleMap.get(ruleId).put(ruleCfg.getDivide(), edgeRule);
443	                }
444	                scheduleEventRuleMap.get(ruleId).get(ruleCfg.getDivide()).getCodeFromList().add(codeFrom);
445	            }
446	        }
447	
448	        // 将scheduleEventRuleMap完全打平
449	        List<ScheduleEdgeRule> scheduleEventRules = scheduleEventRuleMap.values()
450	                .stream()
451	                .flatMap(innerMap -> innerMap.values().stream())
452	                .collect(Collectors.toList());
453	
454	        LOGGER.info("scheduleRebuild数据拼装完成, eventNodes: {}, edgeRules: {}", scheduleEventNodes.size(), scheduleEventRules.size());
455	        ScheduleDAG res = ScheduleDAG.builder()
456	                .scheduleEventNodes(scheduleEventNodes)
457	                .scheduleEdgeRules(scheduleEventRules)
458	                .build();
459	        SCHEDULE_DAG_CACHE.put(version.toString(), JsonUtil.obj2JsonStr(res));
460	        return res;
461	    }
