463	    public String convertNodeCode(String nodeCode, String categoryId, String targetTaskType, Map<String, String> scheduleCodeToCode) {
464	        if (StringUtils.isEmpty(categoryId)) {
465	            // 工期类节点
466	            return scheduleCodeToCode.get(nodeCode);
467	        }
468	        String taskTypeStr = nodeCode.replace("_" + categoryId, "");
469	        if (taskTypeStr.equals("task_generate")) {
470	            // 生成类节点
471	            return categoryId + "_" + scheduleCodeToCode.get(targetTaskType) + "_generate";
472	        }
473	        if (taskTypeStr.startsWith("task_activate")) {
474	            // 激活类节点
475	            return categoryId + "_" + scheduleCodeToCode.get(targetTaskType) + "_active";
476	        }
477	        // 普通品类节点
478	        return categoryId + "_" + scheduleCodeToCode.get(taskTypeStr);
479	
480	    }
