493	    public List<ScheduleEventNode> getFigureNodeList(List<ScheduleEventNode> startNodes, ScheduleAllNode scheduleAllNode) {
494	        initOrderNode(scheduleAllNode);
495	        initDispatchNode(scheduleAllNode);
496	
497	        // startNodes 支持多个起始点
498	        List<ScheduleEventNode> res = new ArrayList<>();
499	        for (ScheduleEventNode startNode : startNodes) {
500	            Stack<String> circleVisited = new Stack<>();
