508	    public List<ScheduleEventNode> getDataNodeList(List<ScheduleEventNode> fugureNodeList, ScheduleAllNode scheduleAllNode) {
509	        // 获取全部需要拉取轨迹的node
510	        Set<ScheduleEventNode> dataNodeSet = new HashSet<>();
511	        for (ScheduleEventNode node : fugureNodeList) {
512	            ScheduleOrderDispatchNode scheduleOrderDispatchNode = getOrderDispatchNode(node, scheduleAllNode);
513	            for (ScheduleNodeEdge edge : node.getEdgeInList()) {
514	                // 只要有符合条件的载体, 就需要拉取数据
515	                if (hasFilterNode(edge.getRuleList(), scheduleOrderDispatchNode)) {
516	                    dataNodeSet.add(edge.getNodeFrom());
517	                    // 验证通过的话, figureNode自身也需要获取时间
518	                    // 因为实际完成时间需要写到考核结果中
519	                    dataNodeSet.add(node);
520	                }
521	            }
522	        }
523	        return new ArrayList<>(dataNodeSet);
524	    }
