526	    private ScheduleOrderDispatchNode getOrderDispatchNode(ScheduleEventNode node, ScheduleAllNode scheduleAllNode) {
527	        ScheduleOrderDispatchNode res = ScheduleOrderDispatchNode.builder()
528	                .orderNodes(new ArrayList<>())
529	                .dispatchNodes(new ArrayList<>())
530	                .build();
531	
532	        // 判断current下是否挂载了任务载体
533	        if (!EVENT_ENTITY.containsKey(node.getName())) {
534	            return res;
535	        }
536	        String categoryId = node.getCategoryId();
537	        List<Integer> entityInfo = EVENT_ENTITY.get(node.getName());
538	        Integer entityType = entityInfo.get(0);
539	        Integer taskType = entityInfo.get(1);
540	
541	        // 根据节点类型, 获取对应的载体列表
542	        if (ORDER_NODE.equals(entityType)) {
543	            res.setOrderNodes(scheduleAllNode.getOrderNodeMap().getOrDefault(categoryId, new HashMap<>()).getOrDefault(taskType, new ArrayList<>()));
544	        }
545	        if (DISPATCH_NODE.equals(entityType)) {
546	            res.setDispatchNodes(scheduleAllNode.getDispatchNodeMap().getOrDefault(categoryId, new HashMap<>()).getOrDefault(taskType, new ArrayList<>()));
547	        }
548	        return res;
549	    }
