551	    private void dfs(ScheduleEventNode current, ScheduleAllNode scheduleAllNode,
552	                     Stack<String> circleVisited, List<ScheduleEventNode> figureNodeList) {
553	        // circleVisited用于判环
554	        // 遇环终止
555	        if (circleVisited.contains(current.getUniqCode())) {
556	            return;
557	        }
558	        circleVisited.push(current.getUniqCode());
559	        for (ScheduleNodeEdge edge : current.getEdgeOutList()) {
560	            ScheduleEventNode nextNode = edge.getNodeTo();
561	            // 存在符合配置的载体, 继续dfs
562	            ScheduleOrderDispatchNode scheduleOrderDispatchNode = getOrderDispatchNode(nextNode, scheduleAllNode);
563	            if (hasFilterNode(edge.getRuleList(), scheduleOrderDispatchNode)) {
564	                figureNodeList.add(nextNode);
565	                dfs(edge.getNodeTo(), scheduleAllNode, circleVisited, figureNodeList);
566	            }
567	        }
568	        circleVisited.pop();
569	    }
