571	    private Boolean hasFilterNode(List<ScheduleEdgeRule> rules, ScheduleOrderDispatchNode scheduleOrderDispatchNode) {
572	        // 符合条件的货单载体(考虑首次配置)
573	        for (ScheduleOrderNode orderNode : scheduleOrderDispatchNode.getOrderNodes()) {
574	            for (ScheduleEdgeRule rule : rules) {
575	                if (rule.getCategoryId().equals(orderNode.getCategoryId())
576	                        && (rule.getDeliveryId().equals("-1") || rule.getDeliveryId().equals(orderNode.getFulfillmentDeliveryId()))
577	                        && (rule.getDeliveryType().equals((byte) -1) || rule.getDeliveryType().equals(orderNode.getDeliveryType()))) {
578	                    return true;
579	                }
580	            }
581	        }
582	
583	        // 符合条件的用工载体(考虑首次配置 & 重启配置)
584	        for (ScheduleDispatchNode dispatchNode : scheduleOrderDispatchNode.getDispatchNodes()) {
585	            for (ScheduleEdgeRule rule : rules) {
586	                if (rule.getCategoryId().equals(dispatchNode.getCategoryId())
587	                        && (rule.getDeliveryId().equals("-1") || rule.getDeliveryId().equals(dispatchNode.getSupplierId()))
588	                        && ((rule.getRestart() && dispatchNode.getRestartCount() > 0)
589	                                || (!rule.getRestart() && dispatchNode.getRestartCount() == 0))) {
590	                    return true;
591	                }
592	            }
593	        }
594	        return false;
595	    }
