597	    private void initOrderNode(ScheduleAllNode scheduleAllNode) {
598	        // {categoryId: {taskType: [ScheduleOrderNode, ...]}}
599	        Map<String, Map<Integer, List<ScheduleOrderNode>>> orderNodeMap = new HashMap<>();
600	        String projectOrderId = scheduleAllNode.getProjectOrderId();
601	
602	        // 除下单任务外的货单任务
603	        IndicatorOrderExample orderExample = new IndicatorOrderExample();
604	        orderExample.createCriteria()
605	                .andProjectOrderIdEqualTo(projectOrderId)
606	                .andIsDeleteEqualTo((byte) 0);
607	        List<IndicatorOrder> orders = indicatorOrderMapper.selectByExample(orderExample);
608	        Map<Long, IndicatorOrder> orderMap = orders.stream()
609	                .collect(Collectors.toMap(IndicatorOrder::getId, o -> o));
610	
611	        for (IndicatorOrder order : orders) {
612	            String categoryId = order.getCategoryId();
613	            if (!orderNodeMap.containsKey(categoryId)) {
614	                orderNodeMap.put(categoryId, new HashMap<>());
615	            }
616	            for (Integer taskType : ORDER_NODE_TASK_TYPES) {
617	                if (!orderNodeMap.get(categoryId).containsKey(taskType)) {
618	                    orderNodeMap.get(categoryId).put(taskType, new ArrayList<>());
619	                }
620	                orderNodeMap.get(categoryId).get(taskType).add(ScheduleOrderNode.builder()
621	                        .id(order.getId())
622	                        .projectOrderId(order.getProjectOrderId())
623	                        .orderNo(order.getOrderNo())
624	                        .taskType(taskType)
625	                        .deliveryType(order.getDeliveryType())
626	                        .categoryId(order.getCategoryId())
627	                        .deliveryId(order.getDeliveryId())
628	                        .supplierId(order.getSupplierId())
629	                        .innerInterval(BigDecimal.ZERO)
630	                        .fulfillmentDeliveryId(order.getDeliveryType() != null && DeliveryTypeEnum.WAREHOUSE.getType().equals(order.getDeliveryType()) ?
631	                                order.getDeliveryId() : order.getSupplierId())
632	                        .replenish(DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(order.getSecondType()))
633	                        .replacement(false)
634	                        .build()
635	                );
636	            }
637	        }
638	
639	        // 下单任务 需要用indicator_project_order和fulfillment_task关联查询
640	        // 仅保留存在对应主材任务的下单载体, 否则计算出结果也没地方存储
641	        IndicatorProjectOrderExample projectExample = new IndicatorProjectOrderExample();
642	        projectExample.createCriteria()
643	                .andProjectOrderIdEqualTo(projectOrderId)
644	                .andIsDeleteEqualTo((byte) 0);
645	        List<IndicatorProjectOrder> projectOrders = indicatorProjectOrderMapper.selectByExample(projectExample);
646	
647	        // 获取下单任务
648	        FulfillmentTaskExample taskExample = new FulfillmentTaskExample();
649	        taskExample.createCriteria()
650	                .andProjectCodeEqualTo(projectOrderId)
651	                .andTaskTypeEqualTo(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode())
652	                .andStatusNotEqualTo(FulfillmentTaskStatusEnum.CANCELED.getTypeCode())
653	                .andIsDeleteEqualTo((byte) 0);
654	        List<FulfillmentTask> placeOrders = fulfillmentTaskMapper.selectByExample(taskExample);
655	        Map<String, FulfillmentTask> existsMap = placeOrders.stream()
656	                .collect(Collectors.toMap(
657	                        o -> o.getCategoryId() + "_" + o.getDeliveryId(),
658	                        Function.identity(),
659	                        (v1, v2) -> v2));
660	
661	        // 获取全部汰换标记
662	        FulfillmentTaskExtExample extExample = new FulfillmentTaskExtExample();
663	        extExample.createCriteria()
664	                .andReplacementEqualTo((byte) 1)
665	                .andProjectOrderIdEqualTo(projectOrderId);
666	        List<FulfillmentTaskExt> extList = fulfillmentTaskExtMapper.selectByExample(extExample);
667	        Set<Long> extSet = extList.stream().map(FulfillmentTaskExt::getTaskId).collect(Collectors.toSet());
668	
669	        projectOrders = projectOrders.stream()
670	                .filter(o -> existsMap.containsKey(o.getCategoryId() + "_" + o.getDeliveryId()))
671	                .collect(Collectors.toList());
672	
673	        Map<Long, IndicatorProjectOrder> projectOrderMap = projectOrders.stream()
674	                .collect(Collectors.toMap(IndicatorProjectOrder::getId, o -> o));
675	
676	        for (IndicatorProjectOrder projectOrder : projectOrders) {
677	            String categoryId = projectOrder.getCategoryId();
678	            if (!orderNodeMap.containsKey(categoryId)) {
679	                orderNodeMap.put(categoryId, new HashMap<>());
680	            }
681	            Integer taskType = FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode();
682	            if (!orderNodeMap.get(categoryId).containsKey(taskType)) {
683	                orderNodeMap.get(categoryId).put(taskType, new ArrayList<>());
684	            }
685	            FulfillmentTask task = existsMap.get(projectOrder.getCategoryId() + "_" + projectOrder.getDeliveryId());
686	            orderNodeMap.get(categoryId).get(taskType).add(ScheduleOrderNode.builder()
687	                    .id(projectOrder.getId())
688	                    .projectOrderId(projectOrder.getProjectOrderId())
689	                    .orderNo("")
690	                    .taskType(taskType)
691	                    .deliveryType(projectOrder.getDeliveryType())
692	                    .categoryId(projectOrder.getCategoryId())
693	                    .deliveryId(projectOrder.getDeliveryId())
694	                    .supplierId("")
695	                    .fulfillmentDeliveryId(projectOrder.getDeliveryId())
696	                    .innerInterval(BigDecimal.ZERO)
697	                    .replenish(false)
698	                    .replacement(extSet.contains(task.getId()))
699	                    .replaceDate(task.getCreateTime())
700	                    .build()
701	            );
702	        }
703	
704	        scheduleAllNode.setOrderNodeMap(orderNodeMap);
705	        scheduleAllNode.setOrderMap(orderMap);
706	        scheduleAllNode.setProjectOrderMap(projectOrderMap);
