741	                            .nodeId(node.getTaskDispatchNodeId())
742	                            .orderNo(task.getOrderNo())
743	                            .taskType(task.getTaskType())
744	                            .nodeType(node.getNodeType())
745	                            .categoryId(categoryId)
746	                            .supplierId(task.getSupplierCode())
747	                            .restartCount(node.getRestartCount())
748	                            .innerInterval(BigDecimal.ZERO)
749	                            .mode(task.getMode())
750	                            .replenish(task.getFlowType() != null && task.getFlowType().equals(FlowTypeEnum.REVERSE_ORDER.getCode()))
751	                            .replacement(replaceTaskIds.contains(task.getTaskDispatchId()))
752	                            .replaceDate(task.getGmtCreate())
753	                            .build()
