784	    public FigureScheduleParam getBaseEventsByActionType(String projectOrderId, Integer actionType, String categoryId) throws RpcException {
785	        ScheduleDAG scheduleDAG = getScheduleDAG(projectOrderId);
786	        if (scheduleDAG == null || CollectionUtils.isEmpty(scheduleDAG.getScheduleEventNodes())) {
787	            return null;
