809	    /**
810	     * 根据主材任务taskType, nodeType, timeType 来寻找对应的事件节点
811	     */
812	    public FigureScheduleParam getBaseEventsByDispatch(String projectOrderId, String categoryId, List<TaskDispatchDetailSimpleDTO.TaskNodeDetail> nodes,
813	                                                       Integer taskType, List<Integer> timeTypes) throws RpcException {
814	
815	        ScheduleDAG scheduleDAG = getScheduleDAG(projectOrderId);
816	        if (scheduleDAG == null || CollectionUtils.isEmpty(scheduleDAG.getScheduleEventNodes())) {
817	            return null;
818	        }
819	
820	        // 拿到DAG中的全部节点
821	        List<ScheduleEventNode> eventNodeList = scheduleDAG.getScheduleEventNodes();
822	
823	        // 将nodes转化为eventNode
824	        Map<String, String> NodeToCodeMap = getAllBaseEvents().stream()
825	                .collect(Collectors.toMap(
826	                        be -> be.getTaskInfo() + "_" + be.getTimeType(),
827	                        IndicatorBaseEvent::getCode,
828	                        (v1, v2) -> v1));
829	
830	        // 拼接taskType_nodeType_timeType作为key, 获取对应的eventNode的uniqCode
831	        Set<String> uniqCodeSet = new HashSet<>();
832	        Set<String> extCodeSet = new HashSet<>();
833	        for (TaskDispatchDetailSimpleDTO.TaskNodeDetail node : nodes) {
834	            Integer nodeType = node.getNodeType();
835	            if (node.getNoticeRetainTime().after(defaultDate) && timeTypes.contains(TimeTypeEnum.NOTICE_TIME.getValue())) {
836	                String key = String.format("%s_%s_%s", taskType, nodeType, TimeTypeEnum.NOTICE_TIME.getValue());
837	                uniqCodeSet.add(categoryId + "_" + NodeToCodeMap.get(key));
838	            }
839	            if (node.getGmtCreate().after(defaultDate) && timeTypes.contains(TimeTypeEnum.CREATE_TIME.getValue())) {
840	                String key = String.format("%s_%s_%s", taskType, nodeType, TimeTypeEnum.CREATE_TIME.getValue());
841	                uniqCodeSet.add(categoryId + "_" + NodeToCodeMap.get(key));
842	            }
843	            if (node.getEndTime().after(defaultDate) && timeTypes.contains(TimeTypeEnum.FACT_TIME.getValue())) {
844	                String key = String.format("%s_%s_%s", taskType, nodeType, TimeTypeEnum.FACT_TIME.getValue());
845	                uniqCodeSet.add(categoryId + "_" + NodeToCodeMap.get(key));
846	            }
847	            if (node.getStartTime().after(defaultDate)
848	                    && (timeTypes.contains(TimeTypeEnum.ACTIVE_TIME.getValue()) || (node.getRestartCount() != null && node.getRestartCount() > 0))) {
849	                // 重启任务的前置条件, 一律视为激活事件
850	                String key = String.format("%s_%s_%s", taskType, nodeType, TimeTypeEnum.ACTIVE_TIME.getValue());
851	                uniqCodeSet.add(categoryId + "_" + NodeToCodeMap.get(key));
852	            }
853	
854	            // 将当前节点(非重启)作为扩展节点, 进行计算
855	            String key = String.format("%s_%s_%s", taskType, nodeType, TimeTypeEnum.FACT_TIME.getValue());
856	            extCodeSet.add(categoryId + "_" + NodeToCodeMap.get(key));
857	        }
858	
859	        uniqCodeSet.remove(null);
860	
861	        return FigureScheduleParam.builder()
862	                .projectOrderId(projectOrderId)
863	                .startNodes(eventNodeList.stream()
864	                        .filter(en -> uniqCodeSet.contains(en.getUniqCode()))
865	                        .collect(Collectors.toList()))
866	                .extNodes(eventNodeList.stream()
867	                        .filter(en -> extCodeSet.contains(en.getUniqCode()) && !uniqCodeSet.contains(en.getUniqCode()))
868	                        .collect(Collectors.toList()))
869	                .build();
870	    }
