913	                    .filter(en -> en.getEventType().equals(EventTypeEnum.BASIC_PACKAGE_SCHEDULE.getValue()))
914	                    .filter(en -> basicNodeCodeSet.contains(String.format("%s_%s", en.getScheduleCode(), en.getCategoryId())))
915	                    .collect(Collectors.toList()));
916	        }
