957	    public Boolean checkConstructionDiff(String projectOrderId, List<DeliveryProcessTaskDTO> tasks) {
958	        Map<String, String> constructionMap = tasks.stream()
959	                .filter(t -> EnumTransformUtil.CONSTRUCTION_ACTION_TYPE_SET.contains(t.getTaskType()))
960	                .collect(Collectors.toMap(
961	                        DeliveryProcessTaskDTO::getNodeCode,
962	                        t -> EvalScheduleOrderService.DEFAULT_TIME.equals(t.getFormTime()) ? t.getPredictStartTime() : t.getFormTime(),
963	                        (v1, v2) -> v1)
964	                );
965	        String value = String.format("%s_%s_%s_%s_%s_%s_%s_%s_%s",
966	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.START_DISCLOSURE.getSequenceCode()),
967	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.TECHNICAL_DISCLOSURE.getSequenceCode()),
968	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.HYDROELECTRIC_ACCEPTANCE.getSequenceCode()),
969	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.WOOD_ACCEPTANCE.getSequenceCode()),
970	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.BASE_COMPLETION_ACCEPTANCE.getSequenceCode()),
971	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.COMPLETION_ACCEPTANCE.getSequenceCode()),
972	                constructionMap.get(ConstructionScheduleSequenceCodeEnum.SOFT_ACCEPTANCE.getSequenceCode()),
973	                constructionMap.get(EnumTransformUtil.FIRST_BATCH_MATERIAL_ACCEPTANCE),
974	                constructionMap.get(EnumTransformUtil.SECOND_BATCH_MATERIAL_ACCEPTANCE));
975	
976	        String key = "scm-workbench:schedule-construction-diff:" + projectOrderId;
977	
978	        // redis不存在数据, 或数据不一致, 返回true
979	        Boolean res = !redisClient.existsKey(key) || !value.equals(redisClient.get(key));
980	        redisClient.set(key, value, apolloConfig.getScheduleInterval());
981	        return res;
982	    }
