994	                time = !EvalScheduleOrderService.DEFAULT_TIME.equals(task.getFactStartTime()) ? task.getFactStartTime() : task.getPredictStartTime();
995	            } else {
996	                time = !EvalScheduleOrderService.DEFAULT_TIME.equals(task.getFactEndTime()) ? task.getFactEndTime() : task.getPredictEndTime();
997	            }
998	            String key = "scm-workbench:schedule-basic-package-diff:" + projectOrderId + ":" + task.getNodeCode();
999	            boolean diff = forceAll || !redisClient.existsKey(key) || !time.equals(redisClient.get(key));
1000	            redisClient.set(key, time, apolloConfig.getScheduleInterval());
1001	            if (diff) {
1002	                res.add(task.getNodeCode());
1003	            }
1004	        }
