205			try {
206				int batchSize = 1000;
207				long currentMinId = minId;
208	
209				while (currentMinId <= maxId) {
210					long currentMaxId = Math.min(currentMinId + batchSize - 1, maxId);
211	
212					EventSubExample example = new EventSubExample();
213					example.createCriteria()
214						  .andIdGreaterThanOrEqualTo(currentMinId)
215						  .andIdLessThanOrEqualTo(currentMaxId);
216	
217					int deletedCount = eventSubMapper.deleteByExample(example);
218					LOGGER.info("删除Kafka事件数据，ID范围[{} - {}]，删除数量：{}", currentMinId, currentMaxId, deletedCount);
219	
220					Thread.sleep(10000);
221					currentMinId = currentMaxId + 1;
222				}
223				resultDTO.success();
224			} catch (Exception e) {
225				LOGGER.error("删除Kafka事件数据失败: ", e);
226			}
227			return resultDTO;
