233			// 新排程考核
234			ResultDTO<Void> resultDTO = new ResultDTO<>();
235	
236			for (String projectOrderId : projectOrderIds) {
237				try {
238					// 白名单开关
239					Boolean scheduleInit = indicatorScheduleDAGService.isScheduleProject(projectOrderId);
240					// 排程开关
241					Boolean inSchedule = edarStarlordRpc.queryProjectInScheduleSwitch(projectOrderId);
242					if (scheduleInit || inSchedule) {
243						// 获取基装包任务
244						List<String> targetTaskTypeList = new ArrayList<>(EnumTransformUtil.BASIC_PACKAGE_ACTION_TYPE_SET);
245						List<DeliveryProcessTaskDTO> tasks = constructionScheduleRpcService.queryScheduleNode(projectOrderId, null, targetTaskTypeList);
246						tasks = tasks.stream()
247								.filter(t -> DeleteStatusEnum.NO.getCode().equals(t.getStandardDeleteStatus()))
248								.collect(Collectors.toList());
249	
250						// 判断基装包节点是否有变化
251						Set<String> basicNodeCodeSet = indicatorScheduleDAGService.checkBasicDiff(projectOrderId, tasks, true);
252	
253						FigureScheduleParam scheduleParam = indicatorScheduleDAGService.getBaseEventsBySchedule(projectOrderId, true, true, basicNodeCodeSet);
254						if (scheduleParam != null) {
255							evalScheduleOrderService.calculateScheduleIndicatorByEvents(projectOrderId, scheduleParam.getStartNodes(), scheduleParam.getExtNodes(), inSchedule);
256						}
257					}
258				} catch (Exception e) {
259					throw new ServiceException(ServiceExceptionEnum.RPC_CALL_FAILURE.getCode(), "排程考核后门计算失败", e);
260				}
