@EntryTrace
@KafkaListener(topics = {"ofc-fulfillment-node"}, containerFactory = "${kafka.config.common-queue-01.consumer.properties.listener-names}")
public void assignInstaller(ConsumerRecord<Long, String> record, Acknowledgment acknowledgment)
