public void calculateIndicatorByEvents(String projectOrderId, List<EventNode> startNodes, List<EventNode> extNodes)
```

**片段 A -- 主流程入口（getFigureNodeList + getDataNodeList + getNodeTimeTrackV2 + doEval）：**

```java
public void calculateIndicatorByEvents(String projectOrderId, List<EventNode> startNodes, List<EventNode> extNodes) {
    // 基础货单数据
    Map<String, List<IndicatorOrder>> orderMap = indicatorDAGService.getOrderMapByProject(projectOrderId);
    Map<String, List<IndicatorProjectOrder>> orderProjectMap = indicatorDAGService.getProjectOrderMapByProject(projectOrderId);

    // 待计算节点
    List<EventNode> figureNodeList = indicatorDAGService.getFigureNodeList(startNodes, extNodes, orderMap, orderProjectMap);

    // 依赖的数据节点
    List<EventNode> dataNodeList = indicatorDAGService.getDataNodeList(figureNodeList, orderMap, orderProjectMap);

    // 基于数据节点, 获取轨迹
    Map<String, List<String>> orderMapByCategory = new HashMap<>();
    for (Map.Entry<String, List<IndicatorOrder>> entry : orderMap.entrySet()) {
        orderMapByCategory.put(entry.getKey(), entry.getValue().stream()
                .map(IndicatorOrder::getOrderNo)
                .collect(Collectors.toList()));
    }
    List<NodeTimeTrackV2> nodeTrackList = getNodeTimeTrackV2(Long.valueOf(projectOrderId), orderMapByCategory, dataNodeList);

    // 预加载该项目下汰换的下单任务创建时间
    Map<String, Date> replacementPlaceOrderCreateTimeMap = buildReplacementPlaceOrderCreateTimeMap(projectOrderId);

    // 数据都准备好了, 开始算数吧
    doEval(figureNodeList, nodeTrackList, orderMap, orderProjectMap, replacementPlaceOrderCreateTimeMap);
}
```

**片段 B -- processRules 中按规则分组、算时间、取最早/最晚的完整逻辑：**

```java
private CalculatedTimeline processRules(Integer sourceType, List<ExtendedEdgeRule> rules, Map<String, NodeTimeTrackV2> timeV2, String orderNo,
                                        IndicatorOrder order, IndicatorProjectOrder projectOrder, Map<LocalDateTime, Integer> calendars,
                                        EventNode eventNode) {
    List<CalculatedTimeline> calculatedTimelines = new ArrayList<>();

    // 按照ruleId分组
    List<List<ExtendedEdgeRule>> sortedGroups = rules.stream()
            .collect(Collectors.groupingBy(EdgeRule::getRuleId))
            .values().stream()
            .sorted(Comparator.comparing((List<ExtendedEdgeRule> group) -> group.get(0).getVersion(), Comparator.nullsLast(Comparator.reverseOrder()))
                    .thenComparing(group -> group.get(0).getEndTime(), Comparator.nullsLast(Comparator.reverseOrder()))
                    .thenComparing(group -> group.get(0).getDeliveryType(), Comparator.nullsLast(Comparator.reverseOrder()))
                    .thenComparing(group -> group.get(0).getDeliveryIds(), Comparator.nullsLast(Comparator.reverseOrder()))
            ).collect(Collectors.toList());

    for (List<ExtendedEdgeRule> groups : sortedGroups) {
        // ... version/time check ...
        Map<Integer, List<ExtendedEdgeRule>> ruleMap = groups.stream()
                .collect(Collectors.groupingBy(EdgeRule::getIndexId));
        for (Map.Entry<Integer, List<ExtendedEdgeRule>> entry : ruleMap.entrySet()) {
            // ... 相同 indexId 内计算每条边的时间 ...
            result.sort(Comparator.comparing(Timeline::getStartTime));
            Timeline timeline = result.get(0);
            // f_ 首次取最早, l_ 最后一次取最晚
            if ("f".equals(eventNode.getPre())) {
                timeTrackRecords.sort(Comparator.comparing(TimeTrackRecord::getTime));
            } else if ("l".equals(eventNode.getPre())) {
                timeTrackRecords.sort(Comparator.comparing(TimeTrackRecord::getTime).reversed());
            }
            // ... TimeProcessor.processTime 算考核时间 ...
            calculatedTimelines.add(calTime);
        }
        CalculatedTimeline calculatedTimeline = selectFinalTimeline(funcName, calculatedTimelines);
        if (calculatedTimeline != null) { return calculatedTimeline; }
    }
    return null;
}

// selectFinalTimeline：依据 funcName 取最早或最晚
public CalculatedTimeline selectFinalTimeline(String funcName, List<CalculatedTimeline> timelines) {
    if ("最早".equals(funcName)) {
        return timelines.stream().min(Comparator.comparing(CalculatedTimeline::getExpectTime, Comparator.nullsLast(Comparator.naturalOrder()))
                .thenComparing(CalculatedTimeline::getExpectStartTime, Comparator.nullsLast(Comparator.naturalOrder()))).orElse(null);
    }
    return timelines.stream().max(Comparator.comparing(CalculatedTimeline::getExpectTime, Comparator.nullsFirst(Comparator.naturalOrder()))
            .thenComparing(CalculatedTimeline::getExpectStartTime, Comparator.nullsFirst(Comparator.naturalOrder()))).orElse(null);
}
