public IndicatorDAG getIndicatorDAG() {
    RAtomicLong redisVersion = redissonClient.getAtomicLong(DAG_VERSION);
    if (redisVersion.get() == 0L) { redisVersion.incrementAndGet(); }
    String cacheString = DAG_CACHE.getOrDefault(IndicatorDAGKey, null);
    if (currentVersion.get() == 0 || currentVersion.get() < redisVersion.get()) {
        cacheString = null;
    }
    if (cacheString == null) {
        synchronized (lock) {
            long currentVer = currentVersion.get();
            long totalVer = redisVersion.get();
            if (currentVer == 0 || currentVer < totalVer) {
                rebuild();
                currentVersion.set(totalVer);
            }
        }
    }
    // 深拷贝 + 重新组装 edgeMap、nodeMap
    // 如果 codeTo 是 l_ 开头，会同时为 f_ 版本的 NodeTo 也创建一条边
    String otherCodeTo = codeTo.replace("l_", "f_");
    // ...
}
