public FigureParam filterEventNodes(String projectOrderId, Integer actionType, String categoryId) {
    IndicatorDAG indicatorDAG = getIndicatorDAG();
    if (Objects.isNull(indicatorDAG) || CollectionUtils.isEmpty(indicatorDAG.getEventNodes())) { return null; }
    List<EventNode> eventNodeList = indicatorDAG.getEventNodes();

    // 查询直接命中的事件, 作为startNode(dfs的起点)
    List<String> targetEvent = Arrays.asList(
            String.format("l_%s_%s", categoryId, actionType),
            String.format("f_%s_%s", categoryId, actionType)
    );
    // 扩展事件
    Set<String> extEventSet = OfcFulfillmentEventHandler.ORDER_ACTION_TYPE_LIST.stream()
            .map(eventType -> String.format("l_%s_%s", categoryId, eventType))
            .collect(Collectors.toSet());

    List<EventNode> starts = eventNodeList.stream()
            .filter(e -> targetEvent.contains(e.getCode())).collect(Collectors.toList());
    List<EventNode> extNodes = eventNodeList.stream()
            .filter(e -> extEventSet.contains(e.getCode())).collect(Collectors.toList());
    return FigureParam.builder()
            .projectOrderNo(projectOrderId).startNodes(starts).extNodes(extNodes).build();
}
