```java
public void doScheduleEval(List<ScheduleEventNode> figureNodeList, List<NodeTimeTrackV2> nodeTrackList,
                           ScheduleAllNode scheduleAllNode, Boolean syncMaterialTask) {
    Map<String, NodeTimeTrackV2> nodeTimeTrackMap = nodeTrackList.stream()
            .collect(Collectors.toMap(NodeTimeTrackV2::getCode, Function.identity(), (v1, v2) -> v1));
    Map<LocalDateTime, Integer> calendars = holidayService.getRecentCalendar();

    for (ScheduleEventNode figureNode : figureNodeList) {
        List<ScheduleEdgeRule> ruleList = flatRules(figureNode.getEdgeInList());
        if (!IndicatorScheduleDAGService.EVENT_ENTITY.containsKey(figureNode.getName())) { continue; }
        List<Integer> entityInfo = IndicatorScheduleDAGService.EVENT_ENTITY.get(figureNode.getName());
        Integer entityType = entityInfo.get(0); // 0=货单, 1=用工
        Integer taskType = entityInfo.get(1);
        String categoryId = figureNode.getCategoryId();

        if (entityType.equals(IndicatorScheduleDAGService.ORDER_NODE)) {
            for (ScheduleOrderNode orderNode : scheduleAllNode.getOrderNodeMap().getOrDefault(categoryId, new HashMap<>()).getOrDefault(taskType, new ArrayList<>())) {
                dealOrderNode(ruleList, orderNode, nodeTimeTrackMap, figureNode, calendars, scheduleAllNode, syncMaterialTask);
            }
        }
        if (entityType.equals(IndicatorScheduleDAGService.DISPATCH_NODE)) {
            for (ScheduleDispatchNode dispatchNode : scheduleAllNode.getDispatchNodeMap().getOrDefault(categoryId, new HashMap<>()).getOrDefault(taskType, new ArrayList<>())) {
                Integer nodeType = entityInfo.get(2);
                if (nodeType.equals(dispatchNode.getNodeType())) {
                    dealDispatchNode(ruleList, dispatchNode, nodeTimeTrackMap, figureNode, calendars, scheduleAllNode, syncMaterialTask);
                }
            }
        }
    }
}
```

