public ScheduleDAG getScheduleDAG(String projectOrderId) throws RpcException {
    Long version = constructionScheduleRpcService.getIndicatorVersion(projectOrderId);
    if (version == null) { return null; }
    String cacheString = SCHEDULE_DAG_CACHE.getIfPresent(version.toString());
    res = StringUtils.isBlank(cacheString) ? rebuild(version) : JsonUtil.jsonStr2Obj(cacheString, ScheduleDAG.class);
    // 初始化edgeMap, 连边
    for (ScheduleEdgeRule edgeRule : res.getScheduleEdgeRules()) {
        for (String codeFrom : edgeRule.getCodeFromList()) {
            String codeTo = edgeRule.getCodeTo();
            ScheduleEventNode nodeFrom = res.getScheduleNodeMap().get(codeFrom);
            ScheduleEventNode nodeTo = res.getScheduleNodeMap().get(codeTo);
            if (nodeFrom == null || nodeTo == null) { continue; }
            String edgeKey = codeFrom + "," + codeTo;
            if (!res.getScheduleEdgeMap().containsKey(edgeKey)) {
                ScheduleNodeEdge nodeEdge = ScheduleNodeEdge.builder()
                        .nodeFrom(nodeFrom).nodeTo(nodeTo).ruleList(new ArrayList<>()).build();
                res.getScheduleEdgeMap().put(edgeKey, nodeEdge);
                nodeFrom.getEdgeOutList().add(nodeEdge);
                nodeTo.getEdgeInList().add(nodeEdge);
            }
            res.getScheduleEdgeMap().get(edgeKey).getRuleList().add(edgeRule);
        }
    }
    // 过滤孤立节点
    res.setScheduleEventNodes(res.getScheduleEventNodes().stream()
            .filter(en -> !(en.getEdgeOutList().isEmpty() && en.getEdgeInList().isEmpty())).collect(Collectors.toList()));
    return res;
}

