84		@Transactional
85		public Pair<Long,String> indicatorBaseConfigCreateOrUpdate(IndicatorBaseConfigModifyParam param) {
86			// 判断是否是新建品类，新建品类时 indicatorUnitList为空
87			if (CollectionUtil.isEmpty(param.getIndicatorUnitList())) {
88				List<IndicatorBaseConfig> indicatorBaseConfigs = indicatorBaseConfigMapper.selectIndicatorBaseConfigByCondition(IndicatorBaseConfigQueryCondition.builder()
89					.categoryId(param.getCategoryId())
90					.orderMode(param.getOrderMode())
91					.build());
92				if (!CollectionUtil.isEmpty(indicatorBaseConfigs)) {
93					return Pair.of(indicatorBaseConfigs.get(0).getId(), "品类已存在，保存后将进入编辑页");
94				}else {
95					IndicatorBaseConfig indicatorBaseConfig = IndicatorBaseConfig.builder()
96						.categoryId(param.getCategoryId())
97						.categoryName(param.getCategoryName())
98						.orderMode(param.getOrderMode())
99						.build();
100					this.indicatorBaseConfigMapper.insertSelective(indicatorBaseConfig);
101					return Pair.of(indicatorBaseConfig.getId(), "");
102				}
103			}
104			IndicatorBaseConfig indicatorBaseConfig = indicatorBaseConfigMapper.selectByPrimaryKey(param.getId());
105			IndicatorBaseConfig snapshot = BeanCoverUtil.covert(indicatorBaseConfig, new IndicatorBaseConfig());
106	
107			// json 替换
108			Integer configType = param.getIndicatorUnitList().get(0).getConfigType();
109			Byte deliveryType = param.getIndicatorUnitList().get(0).getDeliveryType();
110			List<IndicatorUnit.IndicatorRule> indicatorRules = param.getIndicatorUnitList().get(0).getIndicatorRules();
111			// 填充指标ID
112			for(IndicatorUnit.IndicatorRule indicatorRule : indicatorRules) {
113				List<String> names = indicatorRule.getIndicatorDateRules().stream().map(IndicatorUnit.IndicatorDateRule::getIndicatorName).collect(Collectors.toList());
114				List<IndicatorConfig> indicatorConfigs = new ArrayList<>();
115				if (CollectionUtil.isNotEmpty(names)){
116					indicatorConfigs = findIndicatorByNames(names);
117				}
118				Map<String, IndicatorConfig> nameIdMap = indicatorConfigs.stream().collect(Collectors.toMap(IndicatorConfig::getName, Function.identity()));
119				indicatorRule.getIndicatorDateRules().forEach(w -> {
120					w.setId(nameIdMap.get(w.getIndicatorName()).getId());
121					List<IndicatorBO.NodeConf> nodeConfs = JsonUtil.jsonStr2Obj(nameIdMap.get(w.getIndicatorName()).getContent(), new TypeReference<List<IndicatorBO.NodeConf>>() {});
122						nodeConfs.stream().filter(
123								nodeConf -> nodeConf.getHasMeasurementNode().equals(indicatorRule.getHasMeasurementNode())
124								&& nodeConf.getHasDeliveryNotificationNode().equals(indicatorRule.getHasDeliveryNotificationNode())
125								&& nodeConf.getDeliveryType().equals(deliveryType)
126						).findFirst().ifPresent(nodeConf -> {
127							w.setAssessmentRoles(nodeConf.getAssessmentRoles());
128							w.setVisibilityRoles(nodeConf.getVisibilityRoles());
129						});
130				});
131			}
132	
133			List<IndicatorUnit> list = Lists.newArrayList();
134			if(StringUtils.isNotEmpty(indicatorBaseConfig.getContent())) {
135				list = JsonUtil.jsonStr2Obj(indicatorBaseConfig.getContent(), new TypeReference<List<IndicatorUnit>>() {});
136			}
137			//  list 中存在相同的configType和deliveryType时，替换indicatorRules，否则新增IndicatorUnit
138			Optional<IndicatorUnit> optional = list.stream().filter(inu -> inu.getConfigType().equals(configType) && inu.getDeliveryType().equals(deliveryType)).findFirst();
139	
140			if (optional.isPresent()) {
141				// 如果找到了满足条件的元素，就更新它
142				optional.get().setIndicatorRules(indicatorRules);
143			} else {
144				// 如果没有找到满足条件的元素，就创建一个新的元素并添加到列表中
145				IndicatorUnit indicatorUnit = new IndicatorUnit();
146				indicatorUnit.setConfigType(configType);
147				indicatorUnit.setDeliveryType(deliveryType);
148				indicatorUnit.setIndicatorRules(indicatorRules);
149				list.add(indicatorUnit);
150			}
151	
152			indicatorBaseConfig.setContent(JsonUtil.obj2JsonStr(list));
153			// 先存储版本，再把版本号同步到对应的配置表。规则使用时记录该版本号
154			Long versionId = redoLogService.saveRedoLog(null, indicatorBaseConfig);
155			indicatorBaseConfig.setVersion(versionId.intValue());
156			this.indicatorBaseConfigMapper.updateByPrimaryKeySelective(indicatorBaseConfig);
157			// 保存历史记录
158			indicatorHistoryService.saveConfigHis(versionId, param.getIndicatorUnitList().get(0), snapshot);
159			return Pair.of(indicatorBaseConfig.getId(),"");
160		}
