172						.andBusinessVersionEqualTo(param.getBusinessVersion())
173						.andIsDeleteEqualTo((byte) 0);
174				NIndicatorBaseConfig base = nIndicatorBaseConfigMapper.selectOneByExample(example);
175				if (base != null) {
176					return base.getId();
177				}
178				NIndicatorBaseConfig newConfig = IndicatorConfigTransformer.param2NIndicatorBaseConfig(param, commonService.getIndicatorNameConfig(""));
179				indicatorConfigDao.insert(newConfig);
180				return newConfig.getId();
181			}
182	
183			if (param.getCategoryComputeRule() != null && param.getCategoryComputeRule().getDeliveryInfoList() == null) {
184				param.getCategoryComputeRule().setDeliveryInfoList(Collections.singletonList(ComplexQueryRpc.DEFAULT_DELIVERY_INFO));
185			}
186			validateRule(param);
187			NIndicatorBaseConfig baseConfig = nIndicatorBaseConfigMapper.selectByPrimaryKey(param.getSourceId());
188			List<IndicatorComputeRule> indicatorComputeRules = IndicatorComputeRuleTransformer.param2IndicatorComputeRule(param, baseConfig);
189			if (StringUtils.isNotEmpty(param.getHistoryStartTime()) && param.getHistoryVersion() != null) {
190				// 修改最新版本的考核规则
191				indicatorComputeRuleService.updateIndicatorComputeRule(param.getHistoryVersion(), param.getHistoryStartTime(), null, indicatorComputeRules);
192			} else {
193				// 创建新版本的考核规则
194				indicatorComputeRuleService.createIndicatorComputeRule(indicatorComputeRules, null);
195			}
196			// 刷新DAG
197			indicatorDAGService.deleteCache();
198			return param.getSourceId();
199		}
