60		// 修改最新版本的计算规则
61		public void updateIndicatorComputeRule(Integer historyVersion, String historyStartTime, String deliveryInfo, List<IndicatorComputeRule> updateList) {
62	
63			// 先判断是否为最新版本, 只有最新版的数据可以修改
64			Integer sourceType = updateList.get(0).getSourceType();
65			Long sourceId = updateList.get(0).getSourceId();
66			String categoryId = updateList.get(0).getCategoryId();
67			Date startTime = DateUtil.string2Date(historyStartTime);
68	        int newVersion = 0;
69			Date oldStartTime = null;
70	
71			List<IndicatorComputeRule> indicatorComputeRules = bIndicatorComputeRuleMapper.getIndicatorComputeRuleBySourceId(sourceId, sourceType, categoryId, deliveryInfo);
72			Map<String, String> oldMap = new HashMap<>();
73			for (IndicatorComputeRule rule : indicatorComputeRules) {
74				oldMap.put(getDimKey(rule), sourceType.equals(0) ? rule.getBaseComputeRuleNew() : rule.getCusComputeRuleNew());
75				newVersion = Math.max(newVersion, rule.getVersion());
76				if (oldStartTime == null) {
77					oldStartTime = rule.getStartTime();
78				} else if (rule.getStartTime().compareTo(oldStartTime) > 0) {
79					oldStartTime = rule.getStartTime();
80				}
81			}
82	
83			if (!startTime.equals(oldStartTime) || !historyVersion.equals(newVersion)) {
84				throw new IllegalArgumentException("只有最新版本的考核规则才能被修改");
85			}
86	
87			// 修改新版本数据对应的操作日志, 将结束时间设置成跟开始时间相同
88			for (IndicatorComputeRule rule : indicatorComputeRules) {
89				if (IndicatorOrderServiceImpl.DEFAULT_END_TIME.equals(DateUtil.date2String(rule.getEndTime()))
90						&& rule.getVersion().equals(historyVersion)) {
91					IndicatorComputeRuleHistory indicatorComputeRuleHistory = IndicatorComputeRuleHistory.builder()
92							.endTime(startTime)
93							.build();
94					IndicatorComputeRuleHistoryExample historyExample = new IndicatorComputeRuleHistoryExample();
95					historyExample.createCriteria()
96							.andOriginIdEqualTo(rule.getId());
97					indicatorComputeRuleHistoryMapper.updateByExampleSelective(indicatorComputeRuleHistory, historyExample);
98				}
99			}
100	
101			// 删除最新版本的考核数据
102			List<Long> deleteIds = indicatorComputeRules.stream()
103					.filter(o -> startTime.equals(o.getStartTime()) && historyVersion.equals(o.getVersion()))
104					.map(IndicatorComputeRule::getId)
105					.collect(Collectors.toList());
106			if (!deleteIds.isEmpty()) {
107				IndicatorComputeRuleExample example = new IndicatorComputeRuleExample();
108				example.createCriteria()
109						.andIdIn(deleteIds);
110				indicatorComputeRuleMapper.deleteByExample(example);
111			}
112	
113			// 重新创建
114			insertData(sourceType, updateList, historyVersion, oldMap);
115		}
