174		private void insertData(Integer sourceType, List<IndicatorComputeRule> insertList, Integer newVersion, Map<String, String> oldMap) {
175			if (CollectionUtils.isNotEmpty(insertList)) {
176				if (sourceType == 1) {
177					this.validateCusInterval(insertList);
178				}
179				for (IndicatorComputeRule rule : insertList) {
180					rule.setVersion(newVersion);
181					indicatorComputeRuleMapper.insertSelective(rule);
182	
183					IndicatorComputeRuleHistory history = new IndicatorComputeRuleHistory();
184					BeanUtils.copyProperties(rule, history);
185					history.setId(null);
186					history.setCtime(null);
187					history.setMtime(null);
188					history.setEndTime(null);
189					history.setOriginId(rule.getId());
190					history.setOldComputeRuleNew(oldMap.getOrDefault(getDimKey(rule), ""));
191					history.setNewComputeRuleNew(sourceType.equals(0) ? rule.getBaseComputeRuleNew() : rule.getCusComputeRuleNew());
192					history.setOperatorName(CreatorUtils.getCreator());
193					history.setOperatorTime(new Date());
194					history.setStartTime(rule.getStartTime());
195					history.setDeliveryInfo(rule.getDeliveryInfo());
196	
197					CategoryComputeRule.FuncTimeRule oldRule = null;
198					CategoryComputeRule.FuncTimeRule newRule = JsonUtil.jsonStr2Obj(history.getNewComputeRuleNew(), CategoryComputeRule.FuncTimeRule.class);
199					if (StringUtils.isNotEmpty(history.getOldComputeRuleNew())) {
200						oldRule = JsonUtil.jsonStr2Obj(history.getOldComputeRuleNew(), CategoryComputeRule.FuncTimeRule.class);
201					}
202					history.setOperatorDesc(String.format("由【%s】修改为【%s】", oldRule != null ? oldRule.getHumanDesc() : "", newRule.getHumanDesc()));
203	
204					indicatorComputeRuleHistoryMapper.insertSelective(history);
205				}
206			}
207		}
