209		public void validateCusInterval(List<IndicatorComputeRule> cusRuleList) {
210			Map<String, IndicatorComputeRule> cusRuleMap = cusRuleList.stream().collect(Collectors.toMap(this::getDimKey, Function.identity()));
211			IndicatorComputeRule cusRule = cusRuleList.get(0);
212	
213			// 查询对应的底线规则
214			NIndicatorBaseConfigExample baseExample = new NIndicatorBaseConfigExample();
215			baseExample.createCriteria()
216					.andIndicatorNameEqualTo(cusRule.getIndicatorName())
217					.andSecondTypeEqualTo(cusRule.getSecondType())
218					.andBusinessVersionEqualTo(cusRule.getBusinessVersion())
219					.andBusinessTypeEqualTo(cusRule.getBusinessType())
220					.andIsDeleteEqualTo((byte) 0);
221			NIndicatorBaseConfig baseConfig = nIndicatorBaseConfigMapper.selectOneByExample(baseExample);
222			if (baseConfig != null) {
223				List<IndicatorComputeRule> baseComputeRules = bIndicatorComputeRuleMapper.getIndicatorComputeRuleBySourceId(baseConfig.getId(), 0, cusRule.getCategoryId(), null);
224				LOGGER.info("查询到的底线规则为：{}", baseComputeRules);
225				for (IndicatorComputeRule baseRule : baseComputeRules) {
226					IndicatorComputeRule cus = cusRuleMap.get(this.getDimKey(baseRule));
227					if (cus != null && StringUtils.isNotEmpty(cus.getCusComputeRuleNew())) {
228						FuncTimeRule cusFuncTimeRule = JsonUtil.jsonStr2Obj(cus.getCusComputeRuleNew(), FuncTimeRule.class);
229						FuncTimeRule baseFuncTimeRule = JsonUtil.jsonStr2Obj(baseRule.getBaseComputeRuleNew(), FuncTimeRule.class);
230						if (cusFuncTimeRule != null && baseFuncTimeRule != null) {
231							// 比较时间规则
232							diffOne(cusFuncTimeRule, baseFuncTimeRule);
233						}
234					}
235				}
236			}
237		}
