229			// 待计算节点
230			List<EventNode> figureNodeList = indicatorDAGService.getFigureNodeList(startNodes, extNodes, orderMap, orderProjectMap);
231			LOGGER.info("calculateIndicatorByEvents计算节点:{}", JsonUtil.obj2JsonStr(figureNodeList.stream().map(EventNode::getCode).collect(Collectors.toList())));
232	
233			// 依赖的数据节点
234			List<EventNode> dataNodeList = indicatorDAGService.getDataNodeList(figureNodeList, orderMap, orderProjectMap);
235			LOGGER.info("calculateIndicatorByEvents数据节点:{}", JsonUtil.obj2JsonStr(dataNodeList.stream().map(EventNode::getCode).collect(Collectors.toList())));
236	
237			// 基于数据节点, 获取轨迹
238			Map<String, List<String>> orderMapByCategory = new HashMap<>();
239			for (Map.Entry<String, List<IndicatorOrder>> entry : orderMap.entrySet()) {
240				orderMapByCategory.put(entry.getKey(), entry.getValue().stream()
241						.map(IndicatorOrder::getOrderNo)
242						.collect(Collectors.toList()));
243			}
244			List<NodeTimeTrackV2> nodeTrackList = getNodeTimeTrackV2(Long.valueOf(projectOrderId), orderMapByCategory, dataNodeList);
