246			// 预加载该项目下汰换的下单任务（task_type=6）创建时间，key: categoryId_deliveryId → FulfillmentTask.createTime
247			Map<String, Date> replacementPlaceOrderCreateTimeMap = buildReplacementPlaceOrderCreateTimeMap(projectOrderId);
