1170						cus.setRealCompTime(cusReplace.getRealCompTime());
1171						cus.setEvaluation(cusReplace.getEvaluation());
1172					}
1173					cusEvalResult.add(cus);
1174				}
1175				IndicatorOrder updateIndicator = new IndicatorOrder();
1176				updateIndicator.setId(indicatorOrder.getId());
