191		public FulfillmentTask createTask(FulfillmentTaskCreateParam param, Boolean strictCheck) {
192			// 实际创建的方法
193			FulfillmentTask fulfillmentTask = doCreate(param, strictCheck);
194	
195			// 关联批次任务
196			if (FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY.getTypeCode().equals(param.getFulfillmentTaskType())
197					&& param.getProcessBatch() != null && param.getProcessBatch() > 0) {
198				batchDeliveryTaskBizService.createOrJoinDeliveryBatch(fulfillmentTask, fulfillmentTask.getRole(), param.getProcessBatch());
199			}
200	
201			// 如果需要同步主材任务那么 就直接创建
202			if (TaskSyncSystemConf.isMaterialTask(fulfillmentTask.getTaskType())) {
203				TaskOperationContext context = new TaskOperationContext();
204				context.setOperationTime(new Date());
205				context.setTargetStatusEnum(FulfillmentTaskStatusEnum.getEnumByTypeCode(fulfillmentTask.getStatus()));
206				syncMaterialTaskService.doSyncMaterialTask(fulfillmentTask, context);
207			}
208	
209			// 如果存在关联批次任务，还需更新批次送货任务的状态
210			if (fulfillmentTask.getProcessBatch() != null && fulfillmentTask.getProcessBatch() > 0
211					&& fulfillmentTask.getRelateTaskId() != null && fulfillmentTask.getRelateTaskId() > 0) {
212				notifyDeliveryTaskBizService.checkBatchDeliveryTask(fulfillmentTask.getRelateTaskId());
213			}
214			return fulfillmentTask;
215		}
216	
217		private FulfillmentTask doCreate(FulfillmentTaskCreateParam param, Boolean strictCheck) {
218			if (!StringUtil.isEmpty(param.getReceiptOrderNo())) {
219				FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
220				FulfillmentTaskExample.Criteria criteria = fulfillmentTaskExample.createCriteria();
221				criteria.andReceiptNoEqualTo(param.getReceiptOrderNo())
222						.andTaskTypeEqualTo(param.getFulfillmentTaskType())
223						.andReplenishmentEqualTo(param.getReplenishment() != null ? param.getReplenishment() : FlowTypeEnum.NORMAL_ORDER.getCode());
224				if (strictCheck) {
225					criteria.andDeliveryIdEqualTo(param.getSupplierCode())
226							.andCategoryIdEqualTo(param.getCategoryId());
227					if (param.getInitialStatus() != null) {
228						criteria.andStatusEqualTo(param.getInitialStatus());
229					}
230					if (StringUtils.isNotEmpty(param.getRelateSuborderNo())) {
231						criteria.andRelateSubOrderNoEqualTo(param.getRelateSuborderNo());
232					}
233				}
234				FulfillmentTask exist = fulfillmentTaskMapper.selectOneByExample(fulfillmentTaskExample);
235				if (exist != null) {
236					LOGGER.info("FulfillmentTask already exist, subOrderNo:{}", param.getReceiptOrderNo());
237					FulfillmentTask updateFulfilTask = new FulfillmentTask();
238					updateFulfilTask.setId(exist.getId());
239					updateFulfilTask.setStatus(getInitialStatus(exist, param));
240					if (!updateFulfilTask.getStatus().equals(FulfillmentTaskStatusEnum.FINISHED.getTypeCode())) {
241						// 要设置成非完成状态的话, 则重置完成时间
242						updateFulfilTask.setFinishTime(new Date(1000));
243					}
244					fulfillmentTaskMapper.updateByPrimaryKeySelective(updateFulfilTask);
245					// 强制指定一下状态, 当时为了兼容主材进展这里的状态可能有问题
246					exist.setStatus(updateFulfilTask.getStatus());
247					return exist;
248				}
249			}
250	
251			String ftOrderNo = businessNoGenerator.generateFulfillmentTaskOrderNo();
252			FulfillmentTask fulfillmentTask = new FulfillmentTask();
253			fulfillmentTask.setOrderNo(ftOrderNo);
254			fulfillmentTask.setReceiptNo(param.getReceiptOrderNo());
255			fulfillmentTask.setRelateSubOrderNo(param.getRelateSuborderNo());
256			fulfillmentTask.setProjectCode(param.getProjectOrderId());
257			fulfillmentTask.setHomeOrderNo(param.getHomeOrderNo());
258			fulfillmentTask.setDeliveryId(param.getSupplierCode());
259			fulfillmentTask.setDeliveryName(param.getSupplierName());
260			fulfillmentTask.setCategoryId(param.getCategoryId());
261			fulfillmentTask.setCategoryName(param.getCategoryName());
262			fulfillmentTask.setMerchantId(param.getMerchantId());
263			fulfillmentTask.setTaskType(param.getFulfillmentTaskType());
264			fulfillmentTask.setProcessBatch(param.getProcessBatch());
265			fulfillmentTask.setActiveTime(param.getActiveTime() == null ? null : param.getActiveTime());
266			fulfillmentTask.setStatus(getInitialStatus(fulfillmentTask, param));
267			if (param.getReplenishment() != null && param.getReplenishment().equals(FlowTypeEnum.REVERSE_ORDER.getCode())) {
268				fulfillmentTask.setRole(param.getRoleType());
269				fulfillmentTask.setUcid(1000000003L);
270				fulfillmentTask.setName("系统自动");
271				if (param.getUcid() != null) {
272					// 理论上提报, 图纸上传, 下单, 推单走这里
273					fulfillmentTask.setUcid(param.getUcid());
274					fulfillmentTask.setName(param.getName());
275				} else {
276					// 其他节点: 报价, 送货, 接单, 备货, 签收...走这里
277					ProjectServerBaseInfo personBaseInfo = getUcidFromProjectByRole(param.getRelateSuborderNo(),
278							param.getProjectOrderId(), param.getRoleType());
279					if (personBaseInfo != null) {
280						fulfillmentTask.setUcid(personBaseInfo.getUcId());
281						fulfillmentTask.setName(personBaseInfo.getName());
282					}
283				}
284			} else {
285				RoleTypeEnum roleTypeEnum = RoleTypeEnum.getByCode(param.getRoleType());
286				if (roleTypeEnum != null) {
287					fulfillmentTask.setRole(roleTypeEnum.getCode());
288				} else if (com.ke.utopia.enumeration.RoleTypeEnum.getByCode(param.getRoleType()) != null) {
289					fulfillmentTask.setRole(com.ke.utopia.enumeration.RoleTypeEnum.getByCode(param.getRoleType()).getCode());
290				} else {
291					RoleEnum roleEnum = getRoleByRole(param.getRoleType());
292					if (roleEnum != null) {
293						fulfillmentTask.setRole(roleEnum.getRole());
294					}
295				}
296				ProjectServerBaseInfo personBaseInfo = getUcidFromProjectByRole(param.getRelateSuborderNo(),
297						param.getProjectOrderId(), param.getRoleType());
298				fulfillmentTask.setUcid(personBaseInfo.getUcId());
299				fulfillmentTask.setName(personBaseInfo.getName());
300			}
301	
