317		private Integer getInitialStatus(FulfillmentTask fulfillmentTask, FulfillmentTaskCreateParam param) {
318			// 如果预设过初始状态 那么直接进行更新
319			if (param.getInitialStatus() != null) {
320				return param.getInitialStatus();
321			}
322	
323			if (fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY.getTypeCode())
324					|| fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.INSTALL_GET_READY_TO_DELIVERY.getTypeCode())
325					|| fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.PRE_INSTALL_GET_READY_TO_DELIVERY.getTypeCode())
326					|| fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.RECHECK_SCALE_GET_READY_TO_DELIVERY.getTypeCode())
327					|| fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.MEASURE_GET_READY_TO_DELIVERY.getTypeCode())) {
328				return FulfillmentTaskStatusEnum.GENERATED.getTypeCode();
329			}
330			if (fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.DELIVERY_GOODS.getTypeCode())) {
331				// 需要判断前置节点通知可送货节点是否存在.
332				FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
333				FulfillmentTaskExample.Criteria criteria = fulfillmentTaskExample.createCriteria();
334				criteria.andReceiptNoEqualTo(fulfillmentTask.getReceiptNo());
335				criteria.andTaskTypeIn(Lists.newArrayList(FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY.getTypeCode()));
336				criteria.andIsDeleteEqualTo((byte) 0);
337				FulfillmentTask deliveryTask = fulfillmentTaskMapper.selectOneByExample(fulfillmentTaskExample);
338				if (deliveryTask != null) {
339					return FulfillmentTaskStatusEnum.GENERATED.getTypeCode();
340				}
341				return FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode();
342			}
343			if (fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.READY_TO_SIGN.getTypeCode())) {
344				return FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode();
345			}
346			if (FulfillmentTaskTypeEnum.TAKE_ORDER.getTypeCode().equals(fulfillmentTask.getTaskType())
347					|| FulfillmentTaskTypeEnum.STOCKING.getTypeCode().equals(fulfillmentTask.getTaskType())
348					|| FulfillmentTaskTypeEnum.STOCK_IN.getTypeCode().equals(fulfillmentTask.getTaskType())) {
349				return FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode();
350			}
351			if (FulfillmentTaskTypeEnum.QUOTATION_TASK.getTypeCode().equals(fulfillmentTask.getTaskType())) {
352				// 报价任务是激活
353				return FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode();
354			}
355			if (FulfillmentTaskTypeEnum.QUOTATION_ACCEPTANCE_TASK.getTypeCode().equals(fulfillmentTask.getTaskType())) {
356				// 报价验收任务是生成
357				return FulfillmentTaskStatusEnum.GENERATED.getTypeCode();
358			}
359			if (fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode())) {
360				if (param.getRoleType().equals(RoleTypeEnum.SYSTEM_AUTO.getCode())) {
361					return FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode();
362				}
363				return FulfillmentTaskStatusEnum.GENERATED.getTypeCode();
364			}
365			return FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode();
366		}
