522		private Date getAssessmentTime(FulfillmentTask fulfillmentTask, Integer taskMode) {
523			if (fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode())) {
524				return getPlaceOrderAssessmentTime(fulfillmentTask);
525			}
526	
527			// 判断如果场景上没有配置的话 直接跳过
528			HashMap<Integer, String> TaskAssessmentTimeMap = new HashMap<>();
529			String[] templateConfig = taskAssessmentTimeConfig.split(";");
530			for (String config : templateConfig) {
531				String[] timeConfig = config.split(":");
532				TaskAssessmentTimeMap.put(Integer.valueOf(timeConfig[0]), timeConfig[1]);
533			}
534	
535			String indicatorName = TaskAssessmentTimeMap.get(fulfillmentTask.getTaskType());
536			if (indicatorName == null) {
537				return null;
538			}
539			Date assessmentTIme = null;
540			IndicatorOrderExample example = new IndicatorOrderExample();
541			example.createCriteria()
542					.andOrderNoEqualTo(fulfillmentTask.getRelateSubOrderNo())
543					.andIsDeleteEqualTo(IsDeletedEnum.UN_DELETED.getCode());
544			IndicatorOrder indicatorOrder = indicatorOrderMapper.selectOneByExample(example);
545			if (indicatorOrder == null) {
546				LOGGER.info("获取考核时间失败,订单未考核指标未计算:{}", fulfillmentTask.getRelateSubOrderNo());
547				return assessmentTIme;
548			}
549			String relateSubOrderNo = fulfillmentTask.getRelateSubOrderNo();
550			String baseEvalResult = TaskModeEnum.SCHEDULE.getTaskMode().equals(taskMode) ? indicatorOrder.getBaseEvalResult() : indicatorOrder.getBaseEvalResultNew();
551			String cusEvalResult = TaskModeEnum.SCHEDULE.getTaskMode().equals(taskMode) ? indicatorOrder.getCusEvalResult() : indicatorOrder.getCusEvalResultNew();
552	
553			if (StringUtil.isBlank(baseEvalResult)) {
554				LOGGER.info("考核时间计算失败，订单对应的底线配置为空，订单号：{}", relateSubOrderNo);
555				return assessmentTIme;
556			}
557			List<IndicatorEvalValBO.IndicatorEvalSDO> indicatorBaseEvalSDOS = JsonUtil.jsonStr2Obj(baseEvalResult, new TypeReference<List<IndicatorEvalValBO.IndicatorEvalSDO>>() {
558			});
559	
560			IndicatorEvalValBO.IndicatorEvalSDO indicatorEvalSDO = indicatorBaseEvalSDOS.stream().filter(item -> item.getIndicatorName().equals(indicatorName)).findFirst().orElse(null);
561			if (indicatorEvalSDO != null) {
562				assessmentTIme = DateUtil.parse(indicatorEvalSDO.getExpectCompTime(), DateUtil.DATE_FMT_2);
563			}
564	
565			if (StringUtil.isBlank(cusEvalResult)) {
566				LOGGER.info("考核时间计算失败，订单对应的个性化配置为空，订单号：{}", relateSubOrderNo);
567				return assessmentTIme;
568			}
569	
570			List<IndicatorEvalValBO.IndicatorEvalSDO> indicatorCusEvalSDOS = JsonUtil.jsonStr2Obj(cusEvalResult, new TypeReference<List<IndicatorEvalValBO.IndicatorEvalSDO>>() {
571			});
572	
573			IndicatorEvalValBO.IndicatorEvalSDO indicatorCusEval = indicatorCusEvalSDOS.stream()
574					.filter(item -> item.getIndicatorName().equals(indicatorName))
575					.findFirst().orElse(null);
576			if (indicatorCusEval != null) {
577				assessmentTIme = DateUtil.parse(indicatorCusEval.getExpectCompTime(), DateUtil.DATE_FMT_2);
578			}
579			return assessmentTIme;
580		}
