655		/**
656		 * 基于排程品类配置, 生成对应的主材任务
657		 * 一次性生成全部的货单节点(接单 -> 签收, 并激活接单、备货、进仓)
658		**/
659		public void initTask(ScheduleInitParam param) {
660	
661			String orderNo = param.getOrderNo();
662			SubOrderComplexDto subOrderComplexDto;
663			try {
664				subOrderComplexDto = omsRpc.queryBaseByOrderNo(orderNo);
665			} catch (Exception e) {
666				LOGGER.error("查询oms异常, queryBaseByOrderNo orderNo:{}, err:", orderNo, e);
667				return;
668			}
669	
670			// 仅处理白名单内的子订单类型, 辅材单等其他类型不生成排程任务
671			Integer secondType = subOrderComplexDto.getSecondType();
672			boolean isReplenish = DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(secondType)
673					&& StringUtils.isNotEmpty(subOrderComplexDto.getTag())
674					&& subOrderComplexDto.getTag().contains(OrderTagEnum.ALL_CATEGORY_REPLENISH.getCode());
675			if (SecondType.MASTER.getSecondType() != secondType
676					&& SecondType.CENTRAL.getSecondType() != secondType
677					&& SecondType.INTEGRATE_RETAIL_ORDER.getSecondType() != secondType
678					&& SecondType.JINGZHUANG_QUANAN.getSecondType() != secondType
679					&& !isReplenish) {
680				LOGGER.info("initTask skip non-schedule order, orderNo:{}, secondType:{}", orderNo, secondType);
681				return;
682			}
683	
684			// 通用的createParam
685			Integer processBatch = null;
686			FulfillmentTaskCreateParam createParam = initFulfillmentTaskParam(orderNo, orderNo, subOrderComplexDto, RoleTypeEnum.FOREMAN.getCode());
687	
688			// 查询ofc配置的任务列表, 角色列表
689			List<OrderTaskConfDto.TaskConf> ofcTasks;
690			String templateId;
691			try {
692				OrderTaskConfDto conf = ofcRpc.queryAllTaskByOrderNo(orderNo);
693				templateId = conf.getCategoryConfId();
694				ofcTasks = conf.getTaskConfList();
695			} catch (Exception e) {
696				LOGGER.error("查询ofc异常, queryAllTaskByOrderNo orderNo:{}, err:", orderNo, e);
697				return;
698			}
699	
700			List<Integer> taskTypeList = new ArrayList<>();
701			Map<Integer, String> taskRoleMap = new HashMap<>();
702			Map<Integer, String> processCodeMap = new HashMap<>();
703			for (OrderTaskConfDto.TaskConf taskConf : ofcTasks) {
704				for (OrderTaskConfDto.NodeConf nodeConf : taskConf.getNodeConfList()) {
705					if (!TASK_DELIVERY_GOODS_LIST.contains(nodeConf.getTaskDefinitionCode())) {
706						continue;
707					}
708					Integer taskType = CONFIG_TASK_MAP.get(nodeConf.getTaskDefinitionCode());
709					taskTypeList.add(taskType);
710					taskRoleMap.put(taskType, nodeConf.getRoleTypeList().isEmpty() ? null : nodeConf.getRoleTypeList().get(0).getCode());
711					processCodeMap.put(taskType, taskConf.getProcessCode());
712					if (FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY.getTypeCode().equals(taskType)) {
713						UnionRuleEnum unionEnum = UnionRuleEnum.getEnumByValue(nodeConf.getUnionRule());
714						if (unionEnum != null) {
715							processBatch = unionEnum.getBatchNum();
716						}
717					}
718				}
719			}
720	
721			// 对于数据库中不存在的任务, 进行创建
722			FulfillmentTaskExample example = new FulfillmentTaskExample();
723			example.createCriteria()
724					.andRelateSubOrderNoEqualTo(orderNo)
725					.andIsDeleteEqualTo((byte) 0);
726			List<FulfillmentTask> existTasks = fulfillmentTaskMapper.selectByExample(example);
727			Set<Integer> existTaskTypeSet = existTasks.stream()
728					.map(FulfillmentTask::getTaskType)
729					.collect(Collectors.toSet());
730			for (Integer taskType : taskTypeList) {
731				if (existTaskTypeSet.contains(taskType)) {
732					continue;
733				}
734				FulfillmentTaskCreateParam currentParam = new FulfillmentTaskCreateParam();
735				BeanUtils.copyProperties(createParam, currentParam);
736				// 创建不存在的任务, 状态设置为未激活
737				currentParam.setFulfillmentTaskType(taskType);
738				// 通知送货任务的角色存在
739				currentParam.setRoleType(taskRoleMap.get(taskType));
740				currentParam.setInitialStatus(FulfillmentTaskStatusEnum.GENERATED.getTypeCode());
741				currentParam.setTaskMode(TaskModeEnum.SCHEDULE.getTaskMode());
742				// 任务对应的配置信息, 用于starlord激活任务
743				currentParam.setExtInfo(new HashMap<>());
