771		 * 基于排程品类配置, 激活对应的主材任务
772		 **/
773		public void activeTask(ScheduleActiveParam param) {
774	
775			String orderNo = param.getOrderNo();
776			Integer originTaskType = param.getTaskType();
777			Date activeTime = DateUtil.string2Date(param.getOperatingTime());
778	
779			Integer taskType = null;
780			if (TaskTypeEnum.ENTER.getValue().equals(originTaskType)) {
781				// 如果是送货任务的话, 激活通知可送货节点
782				taskType = FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY.getTypeCode();
783			} else if (TaskTypeEnum.ORDER.getValue().equals(originTaskType)) {
784				// 如果是下单任务的话, 激活下单节点
785				taskType = FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode();
786			}
787	
788			if (taskType == null) {
789				LOGGER.info("activeTask 未知的任务类型, orderNo: {}, originTaskType: {}, taskType: {}", orderNo, originTaskType, taskType);
790				return;
791			}
792	
793			// 获取待激活节点
794			// 如果前置节点不存在的话, 激活靠后节点
795			FulfillmentTaskExample example = new FulfillmentTaskExample();
796			FulfillmentTaskExample.Criteria criteria = example.createCriteria();
797			criteria.andTaskTypeEqualTo(taskType);
798			criteria.andIsDeleteEqualTo((byte) 0);
799			if (StringUtils.isNotEmpty(orderNo)) {
800				criteria.andRelateSubOrderNoEqualTo(orderNo);
801			} else if (FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode().equals(taskType)) {
802				criteria.andProjectCodeEqualTo(param.getProjectOrderId());
803				criteria.andCategoryIdEqualTo(param.getCategoryId());
804				criteria.andDeliveryIdEqualTo(param.getSupplierId());
805			} else {
806				return;
807			}
808			List<FulfillmentTask> fulfillmentTasks = fulfillmentTaskMapper.selectByExample(example);
809			if (fulfillmentTasks.isEmpty()) {
810				// 如果前置节点不存在的话, 激活靠后节点
811				if (REPLACE_TASK_MAP.containsKey(taskType)) {
812					example.clear();
813					example.createCriteria()
814							.andRelateSubOrderNoEqualTo(orderNo)
815							.andTaskTypeEqualTo(REPLACE_TASK_MAP.get(taskType))
816							.andIsDeleteEqualTo((byte) 0);
817					fulfillmentTasks = fulfillmentTaskMapper.selectByExample(example);
818				}
819			}
820	
821			// 待激活任务
822			List<FulfillmentTask> needActiveTasks = fulfillmentTasks.stream()
823					.filter(task -> task.getStatus().equals(FulfillmentTaskStatusEnum.GENERATED.getTypeCode()))
824					.collect(Collectors.toList());
825	
826			if (needActiveTasks.isEmpty()) {
827				LOGGER.info("activeTask没找到需要激活的任务");
828				return;
829			}
830	
831			// 处理批次送货
832			for (FulfillmentTask fulfillmentTask : needActiveTasks) {
833				if (fulfillmentTask.getProcessBatch() != null && fulfillmentTask.getProcessBatch() > 0) {
834					notifyDeliveryTaskBizService.checkBatchDeliveryTask(fulfillmentTask.getRelateTaskId());
835				}
836			}
837	
838			// 激活节点
839			example.clear();
840			example.createCriteria()
841					.andIdIn(needActiveTasks.stream().map(FulfillmentTask::getId).collect(Collectors.toList()));
842			TaskOperationContext context = new TaskOperationContext();
843			context.setTargetStatusEnum(FulfillmentTaskStatusEnum.ACTIVATED);
844			context.setOperationTime(activeTime != null ? activeTime : new Date());
845			updateTask(example, context);
846	
847			// 通知送货任务需要检查是否自动完成
848			for (FulfillmentTask task : needActiveTasks) {
849				if (FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY.getTypeCode().equals(task.getTaskType())) {
850					notifyDeliveryTaskBizService.autoFinishNoticeDeliveryTask(task.getRelateSubOrderNo());
851				}
852			}
853		}
