884		/**
885		 * 调度中轴生成任务
886		 * 生成全国的下单
887		 * 如果是全国2.5的项目，还需要检查是否生成设计、报价变更
888		 */
889		public void dealDispatchTask(DispatchTaskDealParam param) throws RpcException {
890			if (CollectionUtils.isEmpty(param.getTaskInitParamList()) && CollectionUtils.isEmpty(param.getTaskCancelParamList())) {
891				LOGGER.info("createDispatchTask没有需要生成/取消的任务, projectOrderId: {}", param.getProjectOrderId());
892				return;
893			}
894	
895			String projectOrderId = param.getProjectOrderId();
896			ProjectOrderDto projectOrderDto = projectOrderRpc.getByProjectOrderId(Long.valueOf(projectOrderId));
897	
898			// 项目在排程配置中, 不创建设计、报价变更任务
899			Boolean isInScheduleConfig = edarStarlordRpc.queryProjectInScheduleSwitch(projectOrderId);
900	
901			// 未切排程的北京项目, 不处理
902			if (apolloConfig.getBeijingBranchCode().contains(projectOrderDto.getHouseDetail().getBranchOfficeCode())
903					&& !isInScheduleConfig) {
904				return;
905			}
906	
907			// 查询货前任务
908			FulfillmentTaskExample example = new FulfillmentTaskExample();
909			example.createCriteria()
910					.andProjectCodeEqualTo(param.getProjectOrderId())
911					.andTaskTypeIn(Arrays.asList(
912							FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode(),
913							FulfillmentTaskTypeEnum.DESIGN_SERVICE.getTypeCode(),
914							FulfillmentTaskTypeEnum.DESIGN_REVIEW.getTypeCode()))
915					.andStatusNotEqualTo(FulfillmentTaskStatusEnum.CANCELED.getTypeCode())
916					.andIsDeleteEqualTo((byte) 0);
917			List<FulfillmentTask> tasks = fulfillmentTaskMapper.selectByExample(example);
918	
919			// 设计、报价变更只能存在一个在途实例
920			// 下单任务只能存在一个实例
921			// 记录每个任务的任务状态, {品类-供应商: {任务: Set<状态>}}
922			Map<String, Map<Integer, Set<Integer>>> taskTypeStatusMap = new HashMap<>();
923			for (FulfillmentTask t : tasks) {
924				String key = t.getCategoryId() + "-" + t.getDeliveryId();
925				if (!taskTypeStatusMap.containsKey(key)) {
926					taskTypeStatusMap.put(key, new HashMap<>());
927				}
928				if (!taskTypeStatusMap.get(key).containsKey(t.getTaskType())) {
929					taskTypeStatusMap.get(key).put(t.getTaskType(), new HashSet<>());
930				}
931				taskTypeStatusMap.get(key).get(t.getTaskType()).add(t.getStatus());
932			}
933	
934			List<FulfillmentTask> createTasks = new ArrayList<>();
935	
936			// 生成下单前任务
937			if (param.getTaskType() == null || param.getTaskType().equals(TaskTypeEnum.DESIGN_REVIEW.getValue())) {
938				createTasks = initPrePlaceOrder(param.getTaskInitParamList(), taskTypeStatusMap, projectOrderDto, isInScheduleConfig);
939			}
940	
941			// 生成下单任务
942			// autoFinish 为重推小工具特殊逻辑
943			boolean autoFinish = TaskTypeEnum.ORDER.getValue().equals(param.getTaskType());
944			if (param.getTaskType() == null || autoFinish) {
945				createTasks.addAll(initPlaceOrder(param.getTaskInitParamList(), taskTypeStatusMap, projectOrderDto, isInScheduleConfig, autoFinish));
946			}
947	
948			// 取消货前任务
949			cancelTask(param.getTaskCancelParamList(), projectOrderId, param.getUsername(), param.getUcid());
950	
951			// 仅汰换场景需要打标
952			if (param.isReplacement()) {
953				try {
954					createReplacementTag(createTasks);
955				} catch (Exception e) {
956					LOGGER.error("createReplacementTag error, projectOrderId: {}, createTasks: {}, err:", projectOrderId, JsonUtil.obj2JsonStr(createTasks), e);
957				}
958			}
959		}
