961		/**
962		 * 调度中轴生成任务
963		 * 全国2.5的设计、报价变更
964		 */
965		public List<FulfillmentTask> initPrePlaceOrder(List<TaskInitParam> taskInitParamList,
966													   Map<String, Map<Integer, Set<Integer>>> taskTypeStatusMap,
967													   ProjectOrderDto projectOrderDto, Boolean isInScheduleConfig) throws RpcException {
968			List<FulfillmentTask> createTasks = new ArrayList<>();
969	
970			// 创建设计、报价变更任务
971			// 进排程的项目不创建设计、报价变更任务
972			if (isInScheduleConfig) {
973				return createTasks;
974			}
975	
976			DispatchConfigBatchQueryParam batchQueryParam = new DispatchConfigBatchQueryParam();
977			batchQueryParam.setWorkFlowConfigIdList(taskInitParamList.stream()
978					.map(TaskInitParam::getConfigurationId)
979					.collect(Collectors.toList()));
980			List<WorkNodeConfigFlattenDto> configList = ofcRpc.queryByFlowConfigIdList(batchQueryParam);
981	
982			// 记录任务角色
983			// {configurationId: {任务: 角色}}
984			Map<Long, Map<Integer, Integer>> roleMap = new HashMap<>();
985			for (WorkNodeConfigFlattenDto config : configList) {
986				Long workFlowConfigId = config.getWorkFlowConfigId();
987				if (!roleMap.containsKey(workFlowConfigId)) {
988					roleMap.put(workFlowConfigId, new HashMap<>());
989				}
990				for (DisPatchNodeConfigDto nodeConfig : config.getDisPatchNodeConfigs()) {
991					if (nodeConfig.getSubFlows() == null) {
992						continue;
993					}
994					for (SubFlowConfigDto subConfig : nodeConfig.getSubFlows()) {
995						for (SubFlowConfigDto.SubNodeDto subFlowConfig : subConfig.getSubFlowNodes()) {
996							// 设计角色
997							if (!roleMap.get(workFlowConfigId).containsKey(FulfillmentTaskTypeEnum.DESIGN_SERVICE.getTypeCode())
998									&& DESIGN_NODE_NAME.equals(nodeConfig.getNodeName())
999									&& TARGET_NODE_CODE.equals(subFlowConfig.getNodeCode())) {
1000								roleMap.get(workFlowConfigId).put(FulfillmentTaskTypeEnum.DESIGN_SERVICE.getTypeCode(), subFlowConfig.getRoleCode());
1001							}
1002							// 报价变更角色
1003							if (!roleMap.get(workFlowConfigId).containsKey(FulfillmentTaskTypeEnum.DESIGN_REVIEW.getTypeCode())
1004									&& DESIGN_REVIEW_NODE_NAME.equals(nodeConfig.getNodeName())
1005									&& TARGET_NODE_CODE.equals(subFlowConfig.getNodeCode())) {
1006								roleMap.get(workFlowConfigId).put(FulfillmentTaskTypeEnum.DESIGN_REVIEW.getTypeCode(), subFlowConfig.getRoleCode());
1007							}
1008						}
1009					}
1010				}
1011			}
1012	
1013			// 初始化任务
1014			for (TaskInitParam taskInitParam : taskInitParamList) {
1015				if (NO_LIMIT_SUPPLIER.equals(taskInitParam.getSupplierId())) {
1016					// 定额复尺这类不限制供应商场景, 不生成任务
1017					continue;
1018				}
1019				Long configurationId = taskInitParam.getConfigurationId();
1020				for (Integer taskType : roleMap.getOrDefault(configurationId, new HashMap<>()).keySet()) {
1021					String key = taskInitParam.getCategoryId() + "-" + taskInitParam.getSupplierId();
1022					// 如果存在未完成的任务, 则不创建
1023					if (taskTypeStatusMap.containsKey(key)
1024							&& taskTypeStatusMap.get(key).containsKey(taskType)
1025							&& UN_FINISH_STATUS.stream().anyMatch(taskTypeStatusMap.get(key).get(taskType)::contains)) {
1026						continue;
1027					}
1028					Integer roleValue = roleMap.get(configurationId).get(taskType);
1029					RoleTypeEnum roleTypeEnum = RoleTypeEnum.getByValue(roleValue);
1030					FulfillmentTaskCreateParam createParam = buildTaskWithoutServiceOrder(projectOrderDto, taskInitParam.getCategoryId(),
1031							taskInitParam.getCategoryName(), taskInitParam.getSupplierId(), taskInitParam.getSupplierName(),
1032							taskType, configurationId.toString(), roleTypeEnum.getCode());
1033					createParam.setSyncSdm(SyncSdmTagEnum.DEFAULT.getValue());
1034					if (RoleTypeEnum.SUPPLIER.getCode().equals(roleTypeEnum.getCode())) {
1035						createParam.setSyncSdm(SyncSdmTagEnum.NEW_SDM.getValue());
1036					}
1037					createTasks.add(createTask(createParam, false));
1038				}
1039			}
1040			return createTasks;
1041		}
