1043		/**
1044		 * 调度中轴生成任务
1045		 * 下单任务
1046		 */
1047		public List<FulfillmentTask> initPlaceOrder(List<TaskInitParam> taskInitParamList, Map<String, Map<Integer, Set<Integer>>> taskTypeStatusMap,
1048													ProjectOrderDto projectOrderDto, Boolean isInScheduleConfig, Boolean autoFinish) throws RpcException {
1049			List<FulfillmentTask> res = new ArrayList<>();
1050	
1051			// 生成下单任务
1052			Map<String, String> groupRoleMap = new HashMap<>();
1053			Map<String, Long> roleUcidMap = new HashMap<>();
1054			String projectVersion = ProjectVersionUtil.getProjectVersionDetail(projectOrderDto);
1055			if (ProjectVersionUtil.V2_5_group_whole.equals(projectVersion)
1056					|| ProjectVersionUtil.V2_5_group_quan.equals(projectVersion)) {
1057				// 团装会提前指定角色
1058				List<String> categoryList = taskInitParamList.stream()
1059						.map(TaskInitParam::getCategoryId)
1060						.distinct().collect(Collectors.toList());
1061				Map<String, List<String>> originRoleMap = constructionMerchantRpc.queryRoleMap(projectVersion, categoryList);
1062				for (String categoryId : originRoleMap.keySet()) {
1063					for (String role : originRoleMap.get(categoryId)) {
1064						if (role != null && !role.equals("test") && !groupRoleMap.containsKey(categoryId)) {
1065							groupRoleMap.put(categoryId, role);
1066						}
1067					}
1068				}
1069				roleUcidMap = projectOrderDto.getProjectServerBaseInfos().stream()
1070						.collect(Collectors.toMap(ProjectServerBaseInfo::getType, ProjectServerBaseInfo::getUcId, (v1, v2) -> v1));
1071			}
1072	
1073			Map<Long, Long> templateConfigMap = new HashMap<>();
1074			if (isInScheduleConfig) {
1075				List<Long> templateIds = taskInitParamList.stream()
1076						.map(TaskInitParam::getConfigurationId)
1077						.collect(Collectors.toList());
1078				if (!templateIds.isEmpty()) {
1079					templateConfigMap = edarStarlordRpc.queryDeliveryCategoryCode(templateIds);
1080				}
1081			}
1082	
1083	
1084			for (TaskInitParam taskInitParam : taskInitParamList) {
1085				SupplierMaterialPair supplierMaterialPair = SupplierMaterialPair.builder()
1086						.materialCode(taskInitParam.getCategoryId())
1087						.materialName(taskInitParam.getCategoryName())
1088						.supplierCode(taskInitParam.getSupplierId())
1089						.supplierName(taskInitParam.getSupplierName())
1090						.orderNo("")
1091						.configurationId(taskInitParam.getConfigurationId().toString())
1092						.build();
1093				if (isInScheduleConfig) {
1094					// 排程下单任务 需要配置id对应的模板存在
1095					Long templateId = taskInitParam.getConfigurationId();
1096					supplierMaterialPair.setTemplateId(templateConfigMap.getOrDefault(templateId, 0L));
1097				}
1098				String key = taskInitParam.getCategoryId() + "-" + taskInitParam.getSupplierId();
1099	
1100				// 如果存在下单任务, 则不创建
1101				if (taskTypeStatusMap.getOrDefault(key, new HashMap<>()).containsKey(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode())) {
1102					continue;
1103				}
1104				res.add(placeOrderTaskBizService.doCreateTask(supplierMaterialPair, projectOrderDto, groupRoleMap, roleUcidMap, isInScheduleConfig));
1105	
1106				if (autoFinish) {
1107					placeOrderTaskBizService.autoFinishTask(projectOrderDto.getProjectOrderId().toString(), taskInitParam.getCategoryId(), taskInitParam.getSupplierId());
1108				}
1109			}
1110			return res;
1111		}
