1387				);
1388	
1389				TaskOperationContext context = new TaskOperationContext();
1390				context.setOperationTime(new Date());
1391				context.setTargetStatusEnum(FulfillmentTaskStatusEnum.FINISHED);
1392				context.setExecutingPartyNo(payLoad.getOrderNo());
1393				context.setReceiptNo(payLoad.getOrderNo());
1394				context.setRelateSubOrderNo(payLoad.getOrderNo());
1395	
1396				this.updateTask(fulfillmentTaskExample, context);
