1447		/**
1448		 * 为主材任务打汰换标
1449		 * 建议异步执行, 以防止影响主流程
1450		 */
1451		private void createReplacementTag(List<FulfillmentTask> tasks) {
1452			List<Long> taskIds = tasks.stream()
1453					.filter(Objects::nonNull)
1454					.map(FulfillmentTask::getId)
1455					.collect(Collectors.toList());
1456			if (taskIds.isEmpty()) {
1457				return;
1458			}
1459	
1460			// 获取待插入的任务列表
1461			FulfillmentTaskExample taskExample = new FulfillmentTaskExample();
1462			taskExample.createCriteria()
1463					.andIdIn(taskIds)
1464					.andIsDeleteEqualTo((byte) 0);
1465			List<FulfillmentTask> fulfillmentTasks = fulfillmentTaskMapper.selectByExample(taskExample);
1466			if (fulfillmentTasks.isEmpty()) {
1467				return;
1468			}
1469	
1470			// 检查是否已插入过汰换标
1471			FulfillmentTaskExtExample extExample = new FulfillmentTaskExtExample();
1472			extExample.createCriteria()
1473					.andTaskIdIn(taskIds)
1474					.andReplacementEqualTo((byte) 1);
1475			List<FulfillmentTaskExt> taskExt = fulfillmentTaskExtMapper.selectByExample(extExample);
1476			Set<Long> replacementTaskIds = taskExt.stream().map(FulfillmentTaskExt::getTaskId).collect(Collectors.toSet());
1477	
1478			// 打汰换标记
1479			fulfillmentTasks = fulfillmentTasks.stream()
1480					.filter(t -> !replacementTaskIds.contains(t.getId()))
1481					.collect(Collectors.toList());
1482			if (fulfillmentTasks.isEmpty()) {
1483				return;
1484			}
1485			List<FulfillmentTaskExt> inserts = fulfillmentTasks.stream()
1486					.map(t -> FulfillmentTaskExt.builder()
1487							.taskId(t.getId())
1488							.projectOrderId(t.getProjectCode())
1489							.relateSubOrderNo(t.getRelateSubOrderNo())
1490							.categoryId(t.getCategoryId())
1491							.categoryName(t.getCategoryName())
1492							.deliveryId(t.getDeliveryId())
1493							.deliveryName(t.getDeliveryName())
1494							.taskType(t.getTaskType())
1495							.replacement((byte) 1)
1496							.build())
1497					.collect(Collectors.toList());
1498			fulfillmentTaskExtMapper.batchInsertSelective(inserts, FulfillmentTaskExt.Column.taskId,
1499					FulfillmentTaskExt.Column.projectOrderId, FulfillmentTaskExt.Column.relateSubOrderNo,
1500					FulfillmentTaskExt.Column.categoryId, FulfillmentTaskExt.Column.categoryName,
1501					FulfillmentTaskExt.Column.deliveryId, FulfillmentTaskExt.Column.deliveryName,
1502					FulfillmentTaskExt.Column.taskType, FulfillmentTaskExt.Column.replacement);
1503	
1504			// 查询任务taskId, 并关联汰换标写入
1505			TaskDispatchDetailSimpleParam starlordParam = new TaskDispatchDetailSimpleParam();
1506			starlordParam.setProjectOrderId(Long.parseLong(fulfillmentTasks.get(0).getProjectCode()));
1507			starlordParam.setTaskStates(Collections.singletonList(YnEnum.YES.getCode()));
1508			starlordParam.setNodeStates(Collections.singletonList(YnEnum.YES.getCode()));
1509	        try {
1510				List<TaskDispatchDetailSimpleDTO> dispatchDetails = edarStarlordRpc.taskDetail(starlordParam);
1511				Map<String, Long> starlordMap = new HashMap<>();
1512				for (TaskDispatchDetailSimpleDTO t : dispatchDetails) {
1513					for (TaskDispatchDetailSimpleDTO.TaskNodeDetail n : t.getTaskNodeDetailList()) {
1514						String key = String.format("%s_%s_%s_%s", t.getMaterialCode(), t.getSupplierCode(), t.getTaskType(), n.getNodeType());
1515						starlordMap.put(key, t.getTaskDispatchId());
1516					}
1517				}
1518				for (FulfillmentTask ft : fulfillmentTasks) {
1519					List<Integer> taskInfo = SyncMaterialTaskService.fulfillmentTaskToMaterialTaskType.get(ft.getTaskType());
1520					if (taskInfo != null && taskInfo.size() == 2) {
1521						String key = String.format("%s_%s_%s_%s", ft.getCategoryId(), ft.getDeliveryId(), taskInfo.get(0), taskInfo.get(1));
1522						if (starlordMap.containsKey(key)) {
1523							Boolean res = edarStarlordRpc.directSaveReplacement(starlordMap.get(key));
1524							if (Boolean.FALSE.equals(res)) {
1525								LOGGER.error("主材任务打汰换标记失败, taskId:{}", starlordMap.get(key));
1526							}
1527						}
1528					}
1529				}
1530			} catch (RpcException e) {
1531				throw new RuntimeException("请求主材任务失败", e);
1532			}
1533	    }
