65		@Override
66		public void handleBiz(OfcDispatchNodeChangePayload payloadData, String eventContextKey) {
67	
68			List<Integer> validNodeList = new ArrayList<>(Arrays.asList(
69				DispatchProcessNodeEnum.ADDITION_COST_AUDIT.getValue(),
70				DispatchProcessNodeEnum.SO_SIGN_FOR.getValue(),
71				DispatchProcessNodeEnum.CHECK_NODE.getValue(),
72				DispatchProcessNodeEnum.SERVER_NODE.getValue()
73			));
74	
75			// 非常规验收场景 或者 非内部角色那么直接过滤
76			if (!validNodeList.contains(payloadData.getNodeCode())) {
77				return;
78			}
79	
80			// 单子启动创建
81			if (ProcessNodeChangeMsgTypeEnum.NODE_START.getCode().equals(payloadData.getMsgType())) {
82				// 设计任务要单独处理 真恶心真恶心真恶心!
83				if (FulfillmentLinkEnum.DESIGN.getValue() == payloadData.getFulfillmentLinkCode()) {
84					FulfillmentTaskCreateParam fulfillmentTaskCreateParam = buildParam(payloadData);
85					if (fulfillmentTaskCreateParam == null) {
86						return;
87					}
88					fulfillmentTaskWriteService.createTask(fulfillmentTaskCreateParam, false);
89					return;
90				}
91				if (!RoleTypeEnum.getByCode(payloadData.getRoleCode()).getCategoryEnum().equals(RoleCategoryEnum.内部通知角色)) {
92					return;
93				}
94				FulfillmentTaskCreateParam fulfillmentTaskCreateParam = buildParam(payloadData);
95				if (fulfillmentTaskCreateParam == null) {
96					return;
97				}
98				if (FulfillmentTaskTypeEnum.READY_TO_SIGN.getTypeCode().equals(fulfillmentTaskCreateParam.getFulfillmentTaskType())) {
99					// 搬走了, 不在这里创建签收任务了
100					return;
101				} else if (FulfillmentTaskTypeEnum.PORTAGE_AUDIT.getTypeCode().equals(fulfillmentTaskCreateParam.getFulfillmentTaskType())) {
102					// 新建搬楼费的时候需要把历史搬楼费的receiptNo修改一下，不然没法新建新的搬楼费任务
103					FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
104					fulfillmentTaskExample.createCriteria()
105							.andReceiptNoEqualTo(fulfillmentTaskCreateParam.getReceiptOrderNo())
106							.andTaskTypeEqualTo(FulfillmentTaskTypeEnum.PORTAGE_AUDIT.getTypeCode());
107					FulfillmentTask target = FulfillmentTask.builder()
108							.receiptNo("")
109							.build();
110					List<FulfillmentTask> audits = fulfillmentTaskMapper.selectByExample(fulfillmentTaskExample);
111					if (!audits.isEmpty()) {
112						List<Long> ids = audits.stream().map(FulfillmentTask::getId).collect(Collectors.toList());
113						fulfillmentTaskExample.clear();
114						fulfillmentTaskExample.createCriteria()
115								.andIdIn(ids);
116						fulfillmentTaskMapper.updateByExampleSelective(target, fulfillmentTaskExample);
117					}
118					fulfillmentTaskWriteService.createTask(fulfillmentTaskCreateParam, false);
119	
120					// 然后再把搬楼费改回来, 绝了, 我真的不想写这种代码
121					if (!audits.isEmpty()) {
122						target.setReceiptNo(fulfillmentTaskCreateParam.getReceiptOrderNo());
123						fulfillmentTaskMapper.updateByExampleSelective(target, fulfillmentTaskExample);
124					}
125				} else {
126					fulfillmentTaskWriteService.createTask(fulfillmentTaskCreateParam, false);
127				}
128			}
129	
130			// 单子完成
131			if (ProcessNodeChangeMsgTypeEnum.NODE_COMPLETE.getCode().equals(payloadData.getMsgType())) {
132				FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
133				FulfillmentTaskExample.Criteria criteria = fulfillmentTaskExample.createCriteria();
134				criteria.andReceiptNoEqualTo(payloadData.getDeliveryOrderNo());
135				criteria.andTaskTypeNotIn(Arrays.asList(
136						FulfillmentTaskTypeEnum.READY_TO_SIGN.getTypeCode(),
137						FulfillmentTaskTypeEnum.AUX_READY_TO_SIGN.getTypeCode()
138				));
139				TaskOperationContext context = new TaskOperationContext();
140				context.setOperationTime(payloadData.getOperatorTime());
141				context.setTargetStatusEnum(FulfillmentTaskStatusEnum.FINISHED);
142				context.setOperatorId(100000001010L);
143				context.setOperatorName("OFC通知完成");
144				fulfillmentTaskWriteService.updateTask(fulfillmentTaskExample, context);
145	
146				// 服务完成场景 进行判断
147				if (DispatchProcessNodeEnum.SERVER_NODE.getValue().equals(payloadData.getNodeCode())) {
148					if (payloadData.getCompleteResult() != null
149							&& payloadData.getCompleteResult().equals(YesNoEnum.NO.getCode())) {
150						// 目前场景单一 不做扩展
151						if (FulfillmentLinkEnum.INSTALL.getValue() == payloadData.getFulfillmentLinkCode()) {
152							fulfillmentTaskWriteService.handleRestart(payloadData.getSubOrderNo(), FulfillmentTaskTypeEnum.INSTALL_GET_READY_TO_DELIVERY);
153						} else if(FulfillmentLinkEnum.EMBEDDED_PARTS_INSTALL.getValue() == payloadData.getFulfillmentLinkCode()) {
154							fulfillmentTaskWriteService.handleRestart(payloadData.getSubOrderNo(), FulfillmentTaskTypeEnum.PRE_INSTALL_GET_READY_TO_DELIVERY);
155						}
156					} else{
157						// 如果服务完成 顺便完成对应的通知类任务
158						List<Integer> taskTypes = FulfillmentTaskTypeEnum.getFulfillmentTaskByDomainType(TaskDomainTypeEnum.通知).stream()
159								.map(FulfillmentTaskTypeEnum::getTypeCode)
160								.collect(Collectors.toList());
161						FulfillmentTaskExample relateFulfillmentExample = new FulfillmentTaskExample();
162						FulfillmentTaskExample.Criteria relateCriteria = relateFulfillmentExample.createCriteria();
163						relateCriteria.andRelateSubOrderNoEqualTo(payloadData.getSubOrderNo());
164						relateCriteria.andTaskTypeIn(taskTypes);
165						relateCriteria.andStatusIn(Arrays.asList(
166								FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode(),
167								FulfillmentTaskStatusEnum.GENERATED.getTypeCode()
168						));
169	
170						TaskOperationContext relateContext = new TaskOperationContext();
171						relateContext.setOperationTime(payloadData.getOperatorTime());
172						relateContext.setTargetStatusEnum(FulfillmentTaskStatusEnum.FINISHED);
173						relateContext.setOperatorId(100000001010L);
174						relateContext.setOperatorName("任务完成");
175						fulfillmentTaskWriteService.updateTask(relateFulfillmentExample, relateContext);
176					}
177				}
178			}
179	
180			// 单子取消
181			if (ProcessNodeChangeMsgTypeEnum.NODE_CANCEL.getCode().equals(payloadData.getMsgType())) {
182				FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
183				fulfillmentTaskExample.createCriteria()
184						.andReceiptNoEqualTo(payloadData.getDeliveryOrderNo())
185						.andIsDeleteEqualTo((byte) 0);
186				TaskOperationContext context = new TaskOperationContext();
187				context.setOperationTime(payloadData.getOperatorTime());
188				context.setTargetStatusEnum(FulfillmentTaskStatusEnum.CANCELED);
189				fulfillmentTaskWriteService.updateTask(fulfillmentTaskExample, context);
190			}
191		}
