84		@Trace
85		@EventListener
86		@Async("IndicatorChangeMsgExecutor")
87		public void handleIndicatorChangedEvent(IndicatorChangedEvent event) {
88			try {
89				LOGGER.info("handleIndicatorChangedEvent eventMsg={}", JsonUtil.obj2JsonStr(event));
90				List<IndicatorEvalValBO.IndicatorEvalSDO> baseEval = event.getBaseEval() != null ? event.getBaseEval() : new ArrayList<>();
91				List<IndicatorEvalValBO.IndicatorEvalSDO> cusEval = event.getCusEval() != null ? event.getCusEval() : new ArrayList<>();
92				Map<String, IndicatorEvalValBO.IndicatorEvalSDO> baseEvalMap = baseEval.stream().collect(Collectors.toMap(IndicatorEvalValBO.IndicatorEvalSDO::getIndicatorName, Function.identity(), (v1, v2) -> v1));
93				Map<String, IndicatorEvalValBO.IndicatorEvalSDO> cusEvalMap = cusEval.stream().collect(Collectors.toMap(IndicatorEvalValBO.IndicatorEvalSDO::getIndicatorName, Function.identity(), (v1, v2) -> v1));
94				Set<String> updatedEval = event.getUpdatedEval();
95				if (updatedEval.isEmpty()) {
96					LOGGER.info("handleIndicatorChangedEvent updatedEval is empty");
97					return;
98				}
99				// 建立消息体
100				String orderNo = event.getOrderNo() == null ? String.valueOf(event.getProjectOrderId()) : event.getOrderNo();
101				Long projectOrderId = event.getProjectOrderId();
102				String branchCode = event.getBranchCode();
103				String categoryId = event.getCategoryId();
104				String deliveryId = event.getDeliveryId();
105				Date synEffectiveTime = DateUtil.parse(apolloConfig.getSynEffectiveTime(), DateUtil.DATE_FMT_3);
106				for (String indicatorName : updatedEval) {
107					IndicatorChangePayload indicatorChangePayload = new IndicatorChangePayload();
108					indicatorChangePayload.setOrderNo(orderNo);
109					indicatorChangePayload.setProjectOrderId(projectOrderId);
110					indicatorChangePayload.setBranchCode(branchCode);
111					indicatorChangePayload.setIndicatorName(indicatorName);
112					indicatorChangePayload.setCategoryId(categoryId);
113					indicatorChangePayload.setDeliveryId(deliveryId);
114					if (event.getFlowType() != null) {
115						indicatorChangePayload.setFlowType(event.getFlowType());
116					}
117	
118					if (baseEvalMap.containsKey(indicatorName)) {
119						IndicatorEvalValBO.IndicatorEvalSDO indicatorEvalSDO = baseEvalMap.get(indicatorName);
120						IndicatorChangePayload.indicatorResultPayLoad indicatorResultPayLoad = indicatorChangePayload.new indicatorResultPayLoad();
121						indicatorResultPayLoad.setIsCusIndicator(indicatorEvalSDO.getIsCusIndicator());
122						indicatorResultPayLoad.setConfigType(indicatorEvalSDO.getConfigType());
123						indicatorResultPayLoad.setExpectCompTime(indicatorEvalSDO.getExpectCompTime());
124						indicatorResultPayLoad.setRealCompTime(indicatorEvalSDO.getRealCompTime());
125						indicatorResultPayLoad.setEvaluation(indicatorEvalSDO.getEvaluation());
126						indicatorChangePayload.setBaseIndicatorResult(indicatorResultPayLoad);
127					}
128	
129					if (cusEvalMap.containsKey(indicatorName)) {
130						IndicatorEvalValBO.IndicatorEvalSDO indicatorEvalSDO = cusEvalMap.get(indicatorName);
131						IndicatorChangePayload.indicatorResultPayLoad indicatorResultPayLoad = indicatorChangePayload.new indicatorResultPayLoad();
132						indicatorResultPayLoad.setIsCusIndicator(indicatorEvalSDO.getIsCusIndicator());
133						indicatorResultPayLoad.setConfigType(indicatorEvalSDO.getConfigType());
134						indicatorResultPayLoad.setExpectCompTime(indicatorEvalSDO.getExpectCompTime());
135						indicatorResultPayLoad.setRealCompTime(indicatorEvalSDO.getRealCompTime());
136						indicatorResultPayLoad.setEvaluation(indicatorEvalSDO.getEvaluation());
137						indicatorChangePayload.setCusIndicatorResult(indicatorResultPayLoad);
138					}
139	
140					// 兼容历史数据格式
141					if (ScheduleEventNameEnum.DELIVERY_GOODS.getName().equals(indicatorChangePayload.getIndicatorName())) {
142						indicatorChangePayload.setIndicatorName("送达及时");
143					}
144	
145					// 开关控制,按照区域及订单创建时间控制
146					if (event.getOrderCreateTime().compareTo(synEffectiveTime) >= 0 && checkValidToProducer(event)) {
147						LOGGER.info("同步主材任务考核时间,orderNo is{},param is {}",orderNo, JsonUtil.obj2JsonStr(indicatorChangePayload));
148						PayLoadData<IndicatorChangePayload> payLoadData = new PayLoadData<>(
149								MessageBizTypeConst.INDICATOR_CHANGED,
150								indicatorChangePayload.getOrderNo(),
151								indicatorChangePayload
152						);
153						producers.send(payLoadData);
154					}
155				}
156			} catch (Exception e) {
157				LOGGER.error("handleIndicatorChangedEvent error, eventMsg={}, error={}", event, e.getMessage(), e);
158			}
159		}
160	
161		private Boolean checkValidToProducer(IndicatorChangedEvent event) {
162			// 北京 && 非排程, 不向供应商同步考核时间。这部分考核是starlord计算并同步的
163			List<String> syncQvyvBlackList = new ArrayList<>(Arrays.asList(apolloConfig.getQvyuBlackList().split(",")));
164			if (!syncQvyvBlackList.contains(event.getQvyu()) || TaskModeEnum.SCHEDULE.getTaskMode().equals(event.getTaskMode())) {
165				return true;
166			}
167	
168			if (event.getProjectOrderId() != null) {
169				ProjectOrderDto projectOrderDto = projectOrderRpc.getByProjectOrderId(event.getProjectOrderId());
170				// 精装全案可以同步
171				if ("hardcover_house".equals(projectOrderDto.getFulfillmentMode())) {
172					return true;
173				}
174	
175				// 团装可以同步
176				String projectVersion = ProjectVersionUtil.getProjectVersionDetail(projectOrderDto);
177				if (ProjectVersionUtil.V2_5_group_whole.equals(projectVersion)
178						|| ProjectVersionUtil.V2_5_group_quan.equals(projectVersion)) {
179					return true;
180				}
181	
182				// 翻新可以同步
183				if (ProjectVersionUtil.V2_5_partial_decoration.equals(projectVersion)) {
184					return true;
185				}
186			}
187			return false;
188		}
