30		public void doSyncOFWTask(FulfillmentTask fulfillmentTask, TaskOperationContext taskOperationContext) {
31	
32			fulfillmentExecutor.execute(() -> {
33	
34				// 供应商模式不同步ofw
35				if (FulfillmentServiceTaskType.SUPPLIER.getTypeCode().equals(fulfillmentTask.getServiceTaskType())
36						|| RoleTypeEnum.SUPPLIER.getCode().equals(fulfillmentTask.getRole())) {
37					return;
38				}
39	
40				// 下服务单之后, 不同步ofw
41				if (StringUtils.isNotEmpty(fulfillmentTask.getReceiptNo()) && fulfillmentTask.getReceiptNo().startsWith("FT")) {
42					return;
43				}
44	
45				if (!taskOperationContext.getTargetStatusEnum().equals(FulfillmentTaskStatusEnum.FINISHED)
46						&& !taskOperationContext.getTargetStatusEnum().equals(FulfillmentTaskStatusEnum.REVIEWING)) {
47					return;
48				}
49	
50				SubOrderEventEnum subOrderEventEnum =  null;
51				switch (taskOperationContext.getTargetStatusEnum()) {
52					case FINISHED:
53						subOrderEventEnum = SubOrderEventEnum.ACCEPTANCE_PASSED;
54						break;
55					case REVIEWING:
56						subOrderEventEnum = SubOrderEventEnum.SERVICE_COMPLETED;
57						break;
58				}
59	
60	            SyncServerOrderStatusParam syncServerOrderStatusParam = new SyncServerOrderStatusParam();
61				syncServerOrderStatusParam.setServiceOrderNo(fulfillmentTask.getReceiptNo());
62				syncServerOrderStatusParam.setOperationTime(taskOperationContext.getOperationTime());
63				syncServerOrderStatusParam.setOperation(subOrderEventEnum.getKey());
