81		public void doSyncMaterialTask(FulfillmentTask fulfillmentTask, TaskOperationContext taskOperationContext) {
82			if (fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.BATCH_DELIVERY.getTypeCode())) {
83				syncDeliveryBatchTask(fulfillmentTask, taskOperationContext);
84				return;
85			}
86			SubOrderComplexDto subOrderComplexDto = null;
87			try {
88				if (StringUtils.isNotBlank(fulfillmentTask.getRelateSubOrderNo())) {
89					subOrderComplexDto = omsRpc.queryBaseByOrderNo(fulfillmentTask.getRelateSubOrderNo());
90				} else if (StringUtils.isNotEmpty(fulfillmentTask.getReceiptNo())) {
91					DeliveryOrderDto deliveryOrderDto = omsRpc.queryDeliveryOrderByOrderNo(fulfillmentTask.getReceiptNo());
92					if (deliveryOrderDto != null) {
93						subOrderComplexDto = omsRpc.queryBaseByOrderNo(deliveryOrderDto.getSubOrderNo());
94					}
95				}
96			} catch (RpcException e) {
97				LOGGER.error("doSyncMaterialTask omsRpc.queryBaseByOrderNo error, fulfillmentTask:{}", JsonUtil.obj2JsonStr(fulfillmentTask), e);
98				return;
99			}
100	
101			if (notSyncMaterialTask(fulfillmentTask, subOrderComplexDto)) {
102				return;
103			}
104	
105			Integer saleType = null;
106			String mdmBranchCode = null;
107			String mdmBranchName = null;
108			if (StringUtils.isNotBlank(fulfillmentTask.getProjectCode())) {
109				ProjectOrderDto projectOrderDto = projectOrderRpc.getByProjectOrderId(Long.valueOf(fulfillmentTask.getProjectCode()));
110				if (projectOrderDto == null) {
111					LOGGER.info("doSyncMaterialTask projectOrderRpc.getByProjectOrderId return null, projectOrderId:{}", fulfillmentTask.getProjectCode());
112					return;
113				}
114				mdmBranchCode = projectOrderDto.getHouseDetail().getBranchOfficeCode();
115				mdmBranchName = projectOrderDto.getHouseDetail().getBranchOfficeName();
116				String projectVersion = ProjectVersionUtil.getProjectVersionDetail(projectOrderDto);
117				if (ProjectVersionUtil.V2_5_group_whole.equals(projectVersion)) {
118					saleType = SaleTypeEnum.TUAN.getCode();
119				} else if (ProjectVersionUtil.V2_5_group_quan.equals(projectVersion)) {
120					saleType = SaleTypeEnum.TUAN_RETAIL.getCode();
121				} else if (ProjectVersionUtil.V2_5_partial_decoration.equals(projectVersion)) {
122					saleType = SaleTypeEnum.PARTIAL_DECORATION.getCode();
123				}
124			}
125	
126			MaterialTaskDirectSaveParam materialTaskDirectSaveParam = new MaterialTaskDirectSaveParam();
127			materialTaskDirectSaveParam.setProjectOrderId(Long.valueOf(fulfillmentTask.getProjectCode()));
128			materialTaskDirectSaveParam.setMdmCode(mdmBranchCode);
129			materialTaskDirectSaveParam.setMdmCompanyName(mdmBranchName);
130			materialTaskDirectSaveParam.setHomeOrderNo(fulfillmentTask.getHomeOrderNo());
131			materialTaskDirectSaveParam.setMaterialCode(fulfillmentTask.getCategoryId());
132			materialTaskDirectSaveParam.setMaterialName(fulfillmentTask.getCategoryName());
133			materialTaskDirectSaveParam.setSupplierCode(fulfillmentTask.getDeliveryId());
134			materialTaskDirectSaveParam.setSupplierName(fulfillmentTask.getDeliveryName());
135			materialTaskDirectSaveParam.setExecutorId(String.valueOf(fulfillmentTask.getUcid()));
136			materialTaskDirectSaveParam.setExecutorName(fulfillmentTask.getName());
137			materialTaskDirectSaveParam.setSubmitName(taskOperationContext.getOperatorName());
138			materialTaskDirectSaveParam.setSubmitTime(fulfillmentTask.getFinishTime());
139			materialTaskDirectSaveParam.setSubmitBy(String.valueOf(taskOperationContext.getOperatorId()));
140			materialTaskDirectSaveParam.setQualified(taskOperationContext.getQualified());
141			materialTaskDirectSaveParam.setFlowType(fulfillmentTask.getReplenishment());
142			materialTaskDirectSaveParam.setProcessBatch(fulfillmentTask.getProcessBatch());
143			materialTaskDirectSaveParam.setNodeReadinessStatus(fulfillmentTask.getAssessmentType());
144			materialTaskDirectSaveParam.setNoticeRetainTime(fulfillmentTask.getNoticeRetainTime());
145			materialTaskDirectSaveParam.setSyncSdmTag(fulfillmentTask.getSyncSdm());
146			materialTaskDirectSaveParam.setStartTime(fulfillmentTask.getActiveTime());
147			materialTaskDirectSaveParam.setEndTime(fulfillmentTask.getFinishTime());
148			// 送货任务的nodeTask和nodePath, 会在findRelateMapping中修改
149			materialTaskDirectSaveParam.setNodeTask("60");
150			materialTaskDirectSaveParam.setNodePath("60000");
151			if (StringUtils.isNotBlank(fulfillmentTask.getExtInfo())) {
152				try {
153					Map<Object, String> extInfoMap = JsonUtil.jsonStr2Obj(fulfillmentTask.getExtInfo(), new TypeReference<Map<Object, String>>(){});
154					materialTaskDirectSaveParam.setTemplateId(Long.parseLong(extInfoMap.getOrDefault("templateId", "0")));
155					materialTaskDirectSaveParam.setProcessCode(extInfoMap.getOrDefault("processCode", ""));
156				} catch (Exception e) {
157					LOGGER.error("doSyncMaterialTask parse extInfo error, fulfillmentTask:{}", JsonUtil.obj2JsonStr(fulfillmentTask), e);
158				}
159			}
160	
161			//设置代办人信息
162			setExecutorType(fulfillmentTask, subOrderComplexDto, materialTaskDirectSaveParam);
163	
164			Map<Object, Object> configIdMap = new HashMap<>();
165			if (StringUtils.isNotBlank(fulfillmentTask.getExtInfo())) {
166				configIdMap = JsonUtil.jsonStr2Obj(fulfillmentTask.getExtInfo(), new TypeReference<Map<Object, Object>>(){});
167			}
168	
169			// 区分八合一配置、排程品类配置
170			materialTaskDirectSaveParam.setMode(TaskModeEnum.ORIGIN.getStarlordMode());
171			TaskModeEnum modeEnum = TaskModeEnum.getTaskModeByMode(fulfillmentTask.getTaskMode());
172			if (modeEnum != null) {
173				materialTaskDirectSaveParam.setMode(modeEnum.getStarlordMode());
174			}
175	
176			if (subOrderComplexDto != null) {
177				materialTaskDirectSaveParam.setOrderNo(subOrderComplexDto.getOrderNo());
178				materialTaskDirectSaveParam.setGbCode(subOrderComplexDto.getGbCode());
179				if (subOrderComplexDto.getSecondType().equals(SecondType.JINGZHUANG_QUANAN.getSecondType())) {
180					saleType = SaleTypeEnum.FINE_TYPE.getCode();
181				}
182			} else {
183				// 从扩展信息里尝试获取GB_CODE
184				if (configIdMap != null && configIdMap.containsKey("gbCode")) {
185					materialTaskDirectSaveParam.setGbCode(String.valueOf(configIdMap.get("gbCode")));
186				}
187				saleType = SaleTypeEnum.PACKAGE_TIED.getCode();
188			}
189			materialTaskDirectSaveParam.setSaleType(saleType != null ? saleType : SaleTypeEnum.PACKAGE_TIED.getCode());
190	
191			if (configIdMap != null) {
192				Object restartCount = configIdMap.getOrDefault("restartCount", null);
193				if (restartCount != null) {
194					materialTaskDirectSaveParam.setRestartCount(Integer.valueOf(String.valueOf(restartCount)));
195				}
196			}
197	
198			if (fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.DESIGN_SERVICE.getTypeCode())) {
199				materialTaskDirectSaveParam.setSourceType(SourceTypeEnum.MEASURE_APPLY_FORM.getType());
200				// 设计服务任务 自营模式下 要把订单号置空 @李向阳
201				if (fulfillmentTask.getServiceTaskType().equals(FulfillmentServiceTaskType.INTERNAL_WORKER.getTypeCode())) {
202					materialTaskDirectSaveParam.setOrderNo(null);
203				}
204			}
205	
206			if (fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.DESIGN_REVIEW.getTypeCode())) {
207				// 报价变更设置服务单号, 但是不设置FT开头的服务单号
208				// FT单号是下架服务单后, workbench内部用于去重的模拟服务单号
209				if (StringUtils.isNotEmpty(fulfillmentTask.getRelateSubOrderNo()) && !fulfillmentTask.getRelateSubOrderNo().startsWith("FT")) {
210					materialTaskDirectSaveParam.setTaskBizRelationIdVo(TaskBizRelationIdVo.builder()
211							.serviceSaleOrderNo(fulfillmentTask.getRelateSubOrderNo())
212							.build());
213				}
214				// 报价变更设置SDO单号
215				if (fulfillmentTask.getReceiptNo() != null && fulfillmentTask.getReceiptNo().startsWith("SDO")) {
216					materialTaskDirectSaveParam.setBusinessId(fulfillmentTask.getReceiptNo());
217				}
218				materialTaskDirectSaveParam.setSourceType(SourceTypeEnum.MEASURE_APPLY_FORM.getType());
219			}
220			if (fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode())) {
221				materialTaskDirectSaveParam.setSourceType(SourceTypeEnum.MEASURE_APPLY_FORM.getType());
222			}
223			materialTaskDirectSaveParam.setEstimatedTime(TaskModeEnum.SCHEDULE.getTaskMode().equals(fulfillmentTask.getTaskMode()) ?
224					fulfillmentTask.getAssessmentEndTime() : fulfillmentTask.getAssessmentTime());
225			setMaterialTaskStatus(taskOperationContext, materialTaskDirectSaveParam);
226			findRelateMapping(fulfillmentTask, materialTaskDirectSaveParam);
227	
228			// 下单任务需要更新为激活未完成或者激活时，单号更新为空
229			if (fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.PLACE_ORDER.getTypeCode())
230					&& (ProcessStatusEnum.UNFINISHED.getValue().equals(materialTaskDirectSaveParam.getTaskProcessStatus())
231						|| ProcessStatusEnum.NOT_ACTIVE.getValue().equals(materialTaskDirectSaveParam.getTaskProcessStatus()))) {
232				materialTaskDirectSaveParam.setOrderNo(null);
233			}
234			try {
235				edarStarlordRpc.directSaveMaterialTask(materialTaskDirectSaveParam);
236			} catch (RpcException e) {
237				LOGGER.error("doSyncMaterialTask edarStarlordRpc.directSaveMaterialTask error, fulfillmentTask:{}", JsonUtil.obj2JsonStr(fulfillmentTask), e);
238			}
239		}
