290		public void syncDeliveryBatchTask(FulfillmentTask fulfillmentTask, TaskOperationContext context) {
291			if (!fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.BATCH_DELIVERY.getTypeCode())) {
292				return;
293			}
294			RoleTypeEnum roleTypeEnum = RoleTypeEnum.getByCode(fulfillmentTask.getRole());
295			com.ke.utopia.scm.ofc.base.enums.conf.RoleTypeEnum ofcRoleType = com.ke.utopia.scm.ofc.base.enums.conf.RoleTypeEnum.getByCode(fulfillmentTask.getRole());
296			TaskProcessBatchDirectSaveParam saveParam = new TaskProcessBatchDirectSaveParam();
297			saveParam.setProjectOrderId(Long.valueOf(fulfillmentTask.getProjectCode()));
298			saveParam.setTaskType(TaskTypeEnum.ENTER.getValue());
299			saveParam.setBatchType(fulfillmentTask.getProcessBatch());
300			saveParam.setProcessStatus(this.convertStarlordTaskProcessStatus(context.getTargetStatusEnum()));
301			saveParam.setState(this.convertStarlordTaskStatus(context.getTargetStatusEnum()));
302			saveParam.setNodeType(NodeTypeEnum.NOTIFY_CAN_START.getValue());
303			saveParam.setActiveTime(fulfillmentTask.getActiveTime());
304			saveParam.setEstimatedTime(fulfillmentTask.getAssessmentTime());
305			saveParam.setExecutorType(roleTypeEnum != null ?
306				roleTypeEnum.getValue().byteValue() : (ofcRoleType == null ? null : ofcRoleType.getValue().byteValue()));
307			saveParam.setExecutorId(String.valueOf(fulfillmentTask.getUcid()));
308			saveParam.setExecutorName(fulfillmentTask.getName());
309			FulfillmentTaskExample relateTaskQuery = new FulfillmentTaskExample();
310	
311			relateTaskQuery.createCriteria()
312					.andProjectCodeEqualTo(fulfillmentTask.getProjectCode())
313					.andRelateTaskIdEqualTo(fulfillmentTask.getId())
314					.andIsDeleteEqualTo(YesNoEnum.NO.getByteCode());
315			List<FulfillmentTask> relateTaskList = fulfillmentTaskMapper.selectByExample(relateTaskQuery);
316			if (CollectionUtils.isNotEmpty(relateTaskList)) {
317				saveParam.setSubOrderNoList(relateTaskList.stream()
318						.map(FulfillmentTask::getRelateSubOrderNo)
319						.collect(Collectors.toList()));
320			}
321			try {
322				edarStarlordRpc.directSaveTaskProcessBatch(saveParam);
323			} catch (RpcException e) {
324				LOGGER.error("doSyncMaterialTask edarStarlordRpc.directSaveTaskProcessBatch error, fulfillmentTask:{}", JsonUtil.obj2JsonStr(fulfillmentTask), e);
325			}
326		}
