328		public boolean notSyncMaterialTask(FulfillmentTask fulfillmentTask, SubOrderComplexDto subOrderComplexDto) {
329			if (subOrderComplexDto != null
330					&& SecondType.MASTER.getSecondType() != subOrderComplexDto.getSecondType()
331					&& SecondType.CENTRAL.getSecondType() != subOrderComplexDto.getSecondType()
332					&& SecondType.INTEGRATE_RETAIL_ORDER.getSecondType() != subOrderComplexDto.getSecondType()
333					&& SecondType.JINGZHUANG_QUANAN.getSecondType() != subOrderComplexDto.getSecondType()
334					&& !(DicRuleNodeQueryServiceImpl.REPLENISH_ALL_SECOND_TYPE_LIST.contains(subOrderComplexDto.getSecondType())
335							&& StringUtils.isNotEmpty(subOrderComplexDto.getTag())
336							&& subOrderComplexDto.getTag().contains(OrderTagEnum.ALL_CATEGORY_REPLENISH.getCode()))) {
337				return true;
338			}
339	
340			if (FulfillmentSystemModeEnum.REFACTOR_NEW.name().equals(fulfillmentTask.getSystemFlowCode())
341					|| FulfillmentSystemModeEnum.BEIWO.name().equals(fulfillmentTask.getSystemFlowCode())) {
342				return true;
343			}
344	
345			if (subOrderComplexDto != null
346					&& apolloConfig.getBeijingBranchCode().contains(subOrderComplexDto.getMdmCode())
347					&& SecondType.JINGZHUANG_QUANAN.getSecondType() != subOrderComplexDto.getSecondType()
348					&& TaskModeEnum.ORIGIN.getTaskMode().equals(fulfillmentTask.getTaskMode())) {
349				return true;
350			}
351	
352			return false;
353		}
