355		public void setExecutorType(FulfillmentTask fulfillmentTask, SubOrderComplexDto subOrderComplexDto,
356									MaterialTaskDirectSaveParam materialTaskDirectSaveParam) {
357			// 我已经要疯了
358			// 如果是送货服务 逻辑特殊
359			if (subOrderComplexDto != null && fulfillmentTask.getTaskType().equals(FulfillmentTaskTypeEnum.DELIVERY_GOODS.getTypeCode())) {
360				materialTaskDirectSaveParam.setExecutorId(fulfillmentTask.getDeliveryId());
361				materialTaskDirectSaveParam.setExecutorName(fulfillmentTask.getDeliveryName());
362				materialTaskDirectSaveParam.setExecutorType(RoleTypeEnum.CARRIER.getValue());
363				if (subOrderComplexDto.getDeliveryType().equals(DeliveryTypeEnum.SUPPLIER.getType())) {
364					materialTaskDirectSaveParam.setExecutorType(RoleTypeEnum.SUPPLIER.getValue());
365				}
366				return;
367			}
368	
369			// 非送货任务
370			if (com.ke.utopia.scm.ofc.base.enums.conf.RoleTypeEnum.SUPPLIER.getCode().equals(fulfillmentTask.getRole())) {
371				materialTaskDirectSaveParam.setExecutorType(RoleTypeEnum.SUPPLIER.getValue());
372			} else if (com.ke.utopia.scm.ofc.base.enums.conf.RoleTypeEnum.SYSTEM_AUTO.getCode().equals(fulfillmentTask.getRole())) {
373				materialTaskDirectSaveParam.setExecutorType(RoleTypeEnum.SYSTEM.getValue());
374			} else {
375				// ofc的家居顾问需要转成starlord的家居顾问
376				com.ke.utopia.scm.ofc.base.enums.conf.RoleTypeEnum ofcRoleEnum = com.ke.utopia.scm.ofc.base.enums.conf.RoleTypeEnum.getByCode(fulfillmentTask.getRole());
377				if (ofcRoleEnum == com.ke.utopia.scm.ofc.base.enums.conf.RoleTypeEnum.JIA_JU_GU_WEN) {
378					materialTaskDirectSaveParam.setExecutorType(RoleTypeEnum.HOME_CONSULTANT.getValue());
379					materialTaskDirectSaveParam.setExecutorId(String.valueOf(fulfillmentTask.getUcid()));
380					materialTaskDirectSaveParam.setExecutorName(fulfillmentTask.getName());
381					return;
382				}
383				// ofc的橱柜导购需要转成starlord的定制业务员
384				if (ofcRoleEnum == com.ke.utopia.scm.ofc.base.enums.conf.RoleTypeEnum.CUSTOM_SALESMAN) {
385					materialTaskDirectSaveParam.setExecutorType(RoleTypeEnum.DING_ZHI_YE_WU_YUAN.getValue());
386					materialTaskDirectSaveParam.setExecutorId(String.valueOf(fulfillmentTask.getUcid()));
387					materialTaskDirectSaveParam.setExecutorName(fulfillmentTask.getName());
