494		private void updateEnterMaterialTaskStatus(FulfillmentTask fulfillmentTask, MaterialTaskDirectSaveParam param) {
495			List<String> nodeTask = new ArrayList<>();
496			List<String> nodePath = new ArrayList<>();
497			if (StringUtil.isEmpty(param.getOrderNo())) {
498				throw new ServiceException(ServiceExceptionEnum.SYNC_ENTER_TASK_EXCEPTION.getCode(), "送货任务的订单号为空");
499			}
500			param.setTaskProcessStatus(ProcessStatusEnum.NOT_ACTIVE.getValue());
501	
502			FulfillmentTaskExample fulfillmentTaskExample = new FulfillmentTaskExample();
503			FulfillmentTaskExample.Criteria criteria = fulfillmentTaskExample.createCriteria();
504			criteria.andRelateSubOrderNoEqualTo(fulfillmentTask.getRelateSubOrderNo());
505			criteria.andTaskTypeIn(Lists.newArrayList(FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY.getTypeCode(),
506					FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY_BATCH.getTypeCode(),
507					FulfillmentTaskTypeEnum.DELIVERY_GOODS.getTypeCode(),
508					FulfillmentTaskTypeEnum.READY_TO_SIGN.getTypeCode()));
509			List<FulfillmentTask> fulfillmentTasks = fulfillmentTaskMapper.selectByExample(fulfillmentTaskExample);
510	
511			// 通知可送货任务
512			FulfillmentTask noticeDeliveryTask = fulfillmentTasks.stream()
513					.filter(item -> item.getTaskType().equals(FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY.getTypeCode())
514							|| item.getTaskType().equals(FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY_BATCH.getTypeCode()))
515					.findAny().orElse(null);
516			if (noticeDeliveryTask != null) {
517				nodeTask.add("20");
518				nodePath.add("20000");
519			}
520	
521			// 送货任务
522			FulfillmentTask deliveryGoodTask = fulfillmentTasks.stream()
523					.filter(item -> item.getTaskType().equals(FulfillmentTaskTypeEnum.DELIVERY_GOODS.getTypeCode()))
524					.findAny().orElse(null);
525			if (deliveryGoodTask != null) {
526				nodeTask.add("60");
527				nodePath.add("60000");
528			}
529	
530			// 签收任务
531			FulfillmentTask readyToSignTask = fulfillmentTasks.stream()
532					.filter(item -> item.getTaskType().equals(FulfillmentTaskTypeEnum.READY_TO_SIGN.getTypeCode()))
533					.findAny().orElse(null);
534			if (readyToSignTask != null) {
535				nodeTask.add("80");
536				nodePath.add("80000");
537			}
538			param.setNodeTask(String.join(",", nodeTask));
539			param.setNodePath(String.join(",", nodePath));
540	
541			// 签收
542			if (readyToSignTask != null) {
543				if (readyToSignTask.getStatus().equals(FulfillmentTaskStatusEnum.FINISHED.getTypeCode())) {
544					param.setTaskProcessStatus(ProcessStatusEnum.FINISHED.getValue());
545				} else if (readyToSignTask.getStatus().equals(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode())) {
546					param.setCurrentNodeType(NodeTypeEnum.FINISH_START.getValue());
547					param.setTaskProcessStatus(ProcessStatusEnum.UNFINISHED.getValue());
548				} else if (readyToSignTask.getStatus().equals(FulfillmentTaskStatusEnum.GENERATED.getTypeCode())) {
549					param.setCurrentNodeType(NodeTypeEnum.START.getValue());
550					param.setTaskProcessStatus(ProcessStatusEnum.UNFINISHED.getValue());
551					if (noticeDeliveryTask != null
552							&& noticeDeliveryTask.getStatus().equals(FulfillmentTaskStatusEnum.GENERATED.getTypeCode())) {
553						// 如果有通知送货任务的话, 且未激活的话
554						param.setCurrentNodeType(NodeTypeEnum.NOTIFY_CAN_START.getValue());
555						param.setTaskProcessStatus(ProcessStatusEnum.NOT_ACTIVE.getValue());
556					} else if (noticeDeliveryTask == null
557							&& deliveryGoodTask != null
558							&& deliveryGoodTask.getStatus().equals(FulfillmentTaskStatusEnum.GENERATED.getTypeCode())) {
559						// 如果没有通知送货任务的话, 但是有送货任务, 且未激活的话
560						param.setTaskProcessStatus(ProcessStatusEnum.NOT_ACTIVE.getValue());
561					}
562				}
563				return;
564			}
565	
566			// 送货任务
567			if (deliveryGoodTask != null && deliveryGoodTask.getStatus().equals(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode())) {
568				param.setCurrentNodeType(NodeTypeEnum.START.getValue());
569				param.setTaskProcessStatus(ProcessStatusEnum.UNFINISHED.getValue());
570				return;
571			} else if (deliveryGoodTask != null && deliveryGoodTask.getStatus().equals(FulfillmentTaskStatusEnum.FINISHED.getTypeCode())) {
572				param.setTaskProcessStatus(null);
573				return;
574			}
575	
576			// 通知送货
577			if (noticeDeliveryTask != null && noticeDeliveryTask.getStatus().equals(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode())) {
578				param.setCurrentNodeType(NodeTypeEnum.NOTIFY_CAN_START.getValue());
579				param.setTaskProcessStatus(ProcessStatusEnum.UNFINISHED.getValue());
580	        }
581		}
