588		public void findRelateMapping(FulfillmentTask fulfillmentTask, MaterialTaskDirectSaveParam param) {
589			Integer taskType = fulfillmentTask.getTaskType();
590			Integer serviceTaskType = fulfillmentTask.getServiceTaskType();
591			FulfillmentTaskTypeEnum fulfillmentTaskTypeEnum = FulfillmentTaskTypeEnum.of(taskType);
592			if (fulfillmentTaskTypeEnum == null) {
593				return ;
594			}
595	
596			// 服务任务
597			if (fulfillmentTaskTypeEnum.equals(FulfillmentTaskTypeEnum.DESIGN_SERVICE)) {
598				param.setTaskType(TaskTypeEnum.DESIGN.getValue());
599				if (serviceTaskType.equals(FulfillmentServiceTaskType.INTERNAL_WORKER.getTypeCode())) {
600					List<ServiceModeEnum> serviceModeListByParentValue = ServiceModeEnum.getServiceModeListByParentValue(ServiceModeEnum.INNER_ROLE.getValue());
601					Optional<ServiceModeEnum> first = serviceModeListByParentValue.stream()
602							.filter(item -> item.getRoleTypeEnum().getCode().equals(fulfillmentTask.getRole()))
603							.findFirst();
604	                first.ifPresent(serviceModeEnum -> param.setServiceMode(serviceModeEnum.getValue()));
605				} else if(serviceTaskType.equals(FulfillmentServiceTaskType.SUPPLIER.getTypeCode())) {
606					param.setServiceMode(ServiceModeEnum.SUPPLY_CHAIN.getValue());
607				}
608				param.setCurrentNodeType(NodeTypeEnum.START.getValue());
609				param.setNodeType(NodeTypeEnum.START.getValue());
610				updateServiceMaterialTaskStatus(fulfillmentTask, param);
611			}
612	
613			// 报价审核任务
614			if (fulfillmentTaskTypeEnum.equals(FulfillmentTaskTypeEnum.DESIGN_REVIEW)) {
615				param.setTaskType(TaskTypeEnum.DESIGN_REVIEW.getValue());
616				if (fulfillmentTask.getServiceTaskType().equals(FulfillmentServiceTaskType.INTERNAL_WORKER.getTypeCode())) {
617					List<ServiceModeEnum> serviceModeListByParentValue = ServiceModeEnum.getServiceModeListByParentValue(ServiceModeEnum.INNER_ROLE.getValue());
618					Optional<ServiceModeEnum> first = serviceModeListByParentValue.stream()
619							.filter(item -> item.getRoleTypeEnum().getCode().equals(fulfillmentTask.getRole()))
620							.findFirst();
621	                first.ifPresent(serviceModeEnum -> param.setServiceMode(serviceModeEnum.getValue()));
622				} else if (fulfillmentTask.getServiceTaskType().equals(FulfillmentServiceTaskType.SUPPLIER.getTypeCode())) {
623					param.setServiceMode(ServiceModeEnum.SUPPLY_CHAIN.getValue());
624				}
625				param.setCurrentNodeType(NodeTypeEnum.START.getValue());
626				param.setNodeType(NodeTypeEnum.START.getValue());
627				updateServiceMaterialTaskStatus(fulfillmentTask, param);
628			}
629	
630			// 下单任务
631			if (fulfillmentTaskTypeEnum.equals(FulfillmentTaskTypeEnum.PLACE_ORDER)) {
632				param.setTaskType(TaskTypeEnum.ORDER.getValue());
633				param.setCurrentNodeType(NodeTypeEnum.START.getValue());
634				param.setNodeType(NodeTypeEnum.START.getValue());
635				updateServiceMaterialTaskStatus(fulfillmentTask, param);
636				param.setOrderNo(fulfillmentTask.getExecutingPartyNo());
637			}
638	
639			// 送货任务
640			if (Lists.newArrayList(FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY.getTypeCode(),
641					FulfillmentTaskTypeEnum.READY_TO_SIGN.getTypeCode(),
642					FulfillmentTaskTypeEnum.DELIVERY_GOODS.getTypeCode(),
643					FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY_BATCH.getTypeCode()).contains(fulfillmentTaskTypeEnum.getTypeCode())) {
644				param.setTaskType(TaskTypeEnum.ENTER.getValue());
645				if (fulfillmentTaskTypeEnum.equals(FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY)
646						|| fulfillmentTaskTypeEnum.equals(FulfillmentTaskTypeEnum.NOTICE_READY_TO_DELIVERY_BATCH)) {
647					param.setNodeType(NodeTypeEnum.NOTIFY_CAN_START.getValue());
648				}
649				if (fulfillmentTaskTypeEnum.equals(FulfillmentTaskTypeEnum.DELIVERY_GOODS)) {
650					param.setNodeType(NodeTypeEnum.START.getValue());
651				}
652				if (fulfillmentTaskTypeEnum.equals(FulfillmentTaskTypeEnum.READY_TO_SIGN)) {
653					param.setNodeType(NodeTypeEnum.FINISH_START.getValue());
654				}
655				updateEnterMaterialTaskStatus(fulfillmentTask, param);
656			}
657	
658			// 接单、备货、进仓任务
659			if (Lists.newArrayList(
660					FulfillmentTaskTypeEnum.TAKE_ORDER.getTypeCode(),
661					FulfillmentTaskTypeEnum.STOCKING.getTypeCode(),
662					FulfillmentTaskTypeEnum.STOCK_IN.getTypeCode()).contains(fulfillmentTaskTypeEnum.getTypeCode())) {
663				param.setCurrentNodeType(NodeTypeEnum.START.getValue());
664				if (FulfillmentTaskTypeEnum.TAKE_ORDER.getTypeCode().equals(fulfillmentTaskTypeEnum.getTypeCode())) {
665					param.setTaskType(TaskTypeEnum.ORDER_TAKING.getValue());
666				}
667				if (FulfillmentTaskTypeEnum.STOCK_IN.getTypeCode().equals(fulfillmentTaskTypeEnum.getTypeCode())) {
668					param.setTaskType(TaskTypeEnum.WAREHOUSE_ENTER.getValue());
669				}
670				if (FulfillmentTaskTypeEnum.STOCKING.getTypeCode().equals(fulfillmentTaskTypeEnum.getTypeCode())) {
671					param.setTaskType(TaskTypeEnum.STOCK_UP.getValue());
672				}
673				param.setNodeType(NodeTypeEnum.START.getValue());
674	
675				// 设置taskProcessStatus
676				updateServiceMaterialTaskStatus(fulfillmentTask, param);
677	
678				// 接单备货进仓 设置currentNodeType
679				if (param.getTaskProcessStatus() != null && param.getTaskProcessStatus().equals(ProcessStatusEnum.FINISHED.getValue())) {
680					param.setCurrentNodeType(1000);
681				}
682			}
683	
684			// 报价任务 报价验收任务
685			if (FulfillmentTaskTypeEnum.QUOTATION_TASK.getTypeCode().equals(fulfillmentTaskTypeEnum.getTypeCode())) {
686				param.setTaskType(TaskTypeEnum.QUOTE.getValue());
687				param.setCurrentNodeType(NodeTypeEnum.START.getValue());
688				param.setNodeType(NodeTypeEnum.START.getValue());
689				param.setTaskProcessStatus(ProcessStatusEnum.UNFINISHED.getValue());
690				if (fulfillmentTask.getStatus().equals(FulfillmentTaskStatusEnum.FINISHED.getTypeCode())) {
691	               param.setEndTime(fulfillmentTask.getFinishTime());
692				}
693			}
694	
695			// 报价验收任务
696			if (FulfillmentTaskTypeEnum.QUOTATION_ACCEPTANCE_TASK.getTypeCode().equals(fulfillmentTaskTypeEnum.getTypeCode())) {
697				param.setTaskType(TaskTypeEnum.QUOTE.getValue());
698				param.setNodeType(NodeTypeEnum.FINISH_START.getValue());
699	
700				// 设置任务状态
701				updateServiceMaterialTaskStatus(fulfillmentTask, param);
702				// 状态未激活时，设置当前节点为60
703				if (fulfillmentTask.getStatus().equals(FulfillmentTaskStatusEnum.GENERATED.getTypeCode())) {
704					// 报价验收任务还未激活，同步主材时当前节点类型还是启动类型节点
705					param.setCurrentNodeType(NodeTypeEnum.START.getValue());
706					// 如果是报价验收节点
707					param.setTaskProcessStatus(ProcessStatusEnum.UNFINISHED.getValue());
708				} else if (fulfillmentTask.getStatus().equals(FulfillmentTaskStatusEnum.ACTIVATED.getTypeCode())) {
709					// 报价验收任务已激活，同步主材时当前节点类型为结束类型节点
710					param.setCurrentNodeType(NodeTypeEnum.FINISH_START.getValue());
711				} else if (fulfillmentTask.getStatus().equals(FulfillmentTaskStatusEnum.FINISHED.getTypeCode())) {
712					// 报价验收任务已完成，同步主材时当前节点类型为1000
713					param.setCurrentNodeType(1000);
714				}
715			}
716		}
717	}
