@Override
public void updateStatus(FulfillmentTask fulfillmentTask, TaskOperationContext taskOperationContext) {
    if (taskOperationContext.getTargetStatusEnum() != null) {
        fulfillmentTask.setStatus(taskOperationContext.getTargetStatusEnum().getTypeCode());
    } else {
        taskOperationContext.setTargetStatusEnum(FulfillmentTaskStatusEnum.getEnumByTypeCode(fulfillmentTask.getStatus()));
    }
    // 如果重新激活场景要处理掉完成时间
    if (taskOperationContext.getTargetStatusEnum().equals(FulfillmentTaskStatusEnum.ACTIVATED)) {
        fulfillmentTask.setFinishTime(new Date(1000));
    }
    // 完成时间
    if (taskOperationContext.getTargetStatusEnum().equals(FulfillmentTaskStatusEnum.FINISHED)) {
        if (fulfillmentTask.getFinishTime() == null || fulfillmentTask.getFinishTime().before(new Date(5000))) {
            fulfillmentTask.setFinishTime(taskOperationContext.getOperationTime() != null ? taskOperationContext.getOperationTime() : new Date());
        }
    }
    // 取消原因
    if (taskOperationContext.getTargetStatusEnum().equals(FulfillmentTaskStatusEnum.CANCELED)) {
        fulfillmentTask.setCancelNote(taskOperationContext.getNote());
        fulfillmentTask.setCancelTime(taskOperationContext.getOperationTime() != null ? taskOperationContext.getOperationTime() : new Date());
    }
    // ... (ucid, name, receiptNo, 考核时间等字段更新)
    fulfillmentTaskMapper.updateByPrimaryKeySelective(fulfillmentTask);

    // 同步主材任务
    if (TaskSyncSystemConf.isMaterialTask(fulfillmentTask.getTaskType())) {
        syncMaterialTaskService.doSyncMaterialTask(fulfillmentTask, taskOperationContext);
    }
    // 同步OFW
    if (TaskSyncSystemConf.isNeedSyncOFWTask(fulfillmentTask.getTaskType())) {
        syncOFWTaskService.doSyncOFWTask(fulfillmentTask, taskOperationContext);
    }
    // 如果存在关联批次任务，还需更新批次送货任务的状态
    if (fulfillmentTask.getProcessBatch() != null && fulfillmentTask.getProcessBatch() > 0
        && fulfillmentTask.getRelateTaskId() != null && fulfillmentTask.getRelateTaskId() > 0) {
