        JavaPairRDD<String, Iterable<Row>> branchRdd = pairRdd.groupByKey().persist(StorageLevel.MEMORY_AND_DISK());
        branchRdd.foreachPartition(rowIterator -> {
            while (rowIterator.hasNext()) {
                Tuple2<String, Iterable<Row>> tuple = rowIterator.next();
                String key = tuple._1;
                Iterable<Row> rows = tuple._2;
                // 处理数据
            }
        });
    }

    public static void pushToCompute(String categoryBranch, Row row) {
        long time = System.currentTimeMillis();
        Map<String, String> params = new HashMap<>();
        params.put("category_id", categoryBranch.substring(0, categoryBranch.indexOf("_")));
        params.put("orderNo", JSONObject.toJSONString(row.getAs("order_no")));
        HttpResponse<String> response = Unirest.post(computeUrl)
                .header("Content-Type", "application/json")
                .connectTimeout(1000)
                .socketTimeout(1000)
                .body(JSONObject.toJSONString(params))
                .asString();
        logger.info("#### {}", JSONObject.toJSONString(params));
        logger.info("############ time:{} code:{} body:{}", System.currentTimeMillis() - time,
                response.getStatus(), response.getBody());
    }
}
```

说明：JavaJobDemo 是 Spark 批处理入口，main() 创建 SparkSession 并调用 run()。run() 从 Hive 执行 SQL（在途销售单，排除集采），repartition 后按 category_id+branch_code 分组，foreachPartition 遍历分组数据。`pushToCompute()` 是对考核服务的 HTTP 调用，用 Unirest 将品类和订单号 POST 到 computeUrl，触发批量重算。sql 和 computeUrl 字段（实际由 Spring 配置注入）未包含在代码片段中。

