```java
@Override
public ResultDTO<Void> activeDeliveryNotifyTask(String projectOrderId) {
    ResultDTO<Void> resultDTO = new ResultDTO<>();
    resultDTO.success();

    String redisKey = redisClient.generateKey(projectOrderId + "_activeDeliveryNotifyTask");
    if (redisClient.existsKey(redisKey)) {
        LOGGER.info("activeDeliveryNotifyTask不处理, 请求过于频繁, project:{}", projectOrderId);
        return resultDTO;
    }
    redisClient.set(redisKey, "", 60 * 5);
    notifyDeliveryTaskBizService.tryActiveNoticeDeliveryTaskForProject(Long.valueOf(projectOrderId));
    return resultDTO;
}
