268		public String getDimKey(IndicatorComputeRule rule) {
269			return Joiner.on(",").join(rule.getCategoryId(), rule.getDeliveryType(), rule.getHasMeasurementNode(), rule.getHasDeliveryNotificationNode());
270		}
