272		public void delRule(Integer sourceType, Long sourceId) {
273			IndicatorComputeRuleExample example = new IndicatorComputeRuleExample();
274			example.createCriteria()
275					.andSourceTypeEqualTo(sourceType)
276					.andSourceIdEqualTo(sourceId);
277			List<IndicatorComputeRule> indicatorComputeRules = indicatorComputeRuleMapper.selectByExample(example);
278	
279			if (CollectionUtils.isNotEmpty(indicatorComputeRules)) {
280				Long versionId = redoLogService.saveRedoLog(null, indicatorComputeRules);
281				indicatorComputeRules.forEach(rule -> {
282					this.indicatorHistoryService.saveLog(versionId, rule.getSourceType().equals(0) ? 2 : 3, null, rule);
283					this.indicatorComputeRuleDao.delete(rule.getId());
284				});
285			}
286		}
