135				list = JsonUtil.jsonStr2Obj(indicatorBaseConfig.getContent(), new TypeReference<List<IndicatorUnit>>() {});
136			}
137			//  list 中存在相同的configType和deliveryType时，替换indicatorRules，否则新增IndicatorUnit
138			Optional<IndicatorUnit> optional = list.stream().filter(inu -> inu.getConfigType().equals(configType) && inu.getDeliveryType().equals(deliveryType)).findFirst();
139	
140			if (optional.isPresent()) {
141				// 如果找到了满足条件的元素，就更新它
142				optional.get().setIndicatorRules(indicatorRules);
143			} else {
144				// 如果没有找到满足条件的元素，就创建一个新的元素并添加到列表中
145				IndicatorUnit indicatorUnit = new IndicatorUnit();
146				indicatorUnit.setConfigType(configType);
147				indicatorUnit.setDeliveryType(deliveryType);
148				indicatorUnit.setIndicatorRules(indicatorRules);
149				list.add(indicatorUnit);
150			}
151	
152			indicatorBaseConfig.setContent(JsonUtil.obj2JsonStr(list));
153			// 先存储版本，再把版本号同步到对应的配置表。规则使用时记录该版本号
154			Long versionId = redoLogService.saveRedoLog(null, indicatorBaseConfig);
155			indicatorBaseConfig.setVersion(versionId.intValue());
156			this.indicatorBaseConfigMapper.updateByPrimaryKeySelective(indicatorBaseConfig);
157			// 保存历史记录
158			indicatorHistoryService.saveConfigHis(versionId, param.getIndicatorUnitList().get(0), snapshot);
159			return Pair.of(indicatorBaseConfig.getId(),"");
160		}
