114		public Pair<Long,String> indicatorCusConfigCreateOrUpdate(IndicatorCusConfigModifyParam param) {
115			// 需要按照品类整体维度进行重复判断，如果规则冲突，直接阻止创建
116			if(param.getId() == null) {
117				Validate.notEmpty(param.getQvyu());
118				List<DicBranchCompanyDto> dicBranchCompanyDtos = this.getBranchInfoByAreaName(param.getQvyu());
119				// 新增
120				if(GranularityTypeEnum.LEVEL_2.getType().equals(param.getGranularityType())) { // 配置区域维度时
121					// 配置区域维度时,补充签约主体信息
122					param.setBranchInfoDtoList(dicBranchCompanyDtos.stream()
123						.map(w -> new IndicatorCusConfigModifyParam.BranchInfoDto(w.getBranchCompanyCode(),w.getBranchCompanyName()))
124						.collect(Collectors.toList()));
125				}
126				Validate.notEmpty(param.getBranchInfoDtoList());
127				param.setZhanqv(dicBranchCompanyDtos.get(0).getTheaterName());
128	
129				Optional<IndicatorCategoryConfig> categoryConfig = this.findByCategoryId(param.getCategoryId());
130				List<CategoryConfDetail> newList = param.getBranchInfoDtoList().stream().map(branch -> new CategoryConfDetail(
131					param.getCategoryId(),
132					param.getCategoryName(),
133					param.getGranularityType(),
134					param.getQvyu(),
135					branch.getBranchCode(),
136					param.getMerchantId(),
137					param.getDeliveryId()
138				)).collect(Collectors.toList());
139	
140				if(categoryConfig.isPresent()) {
141					List<CategoryConfDetail> categoryConfDetails = JsonUtil.jsonStr2Obj(categoryConfig.get().getContext(), new TypeReference<List<CategoryConfDetail>>() {});
142					List<CategoryConfDetail> union = CollectionUtil.getIntersection(categoryConfDetails, newList);
143					if(!union.isEmpty()) {
144						throw new IllegalArgumentException("一城一策配置已存在,重复配置内容：" + union);
145					}
146					newList.addAll(categoryConfDetails);
147					indicatorCategoryConfigMapper.updateByPrimaryKeySelective(IndicatorCategoryConfig
148						.builder().id(categoryConfig.get().getId()).context(JsonUtil.obj2JsonStr(newList)).build());
149				} else {
150					this.indicatorCategoryConfigMapper.insertSelective(IndicatorCategoryConfig.builder()
151						.categoryId(param.getCategoryId())
152						.context(JsonUtil.obj2JsonStr(newList))
153						.build());
154				}
155	
156				// 保存维度配置
157				IndicatorCusConfig indicatorCusConfig = IndicatorCusConfig.builder()
158					.branchCode(param.getBranchInfoDtoList().stream().map(IndicatorCusConfigModifyParam.BranchInfoDto::getBranchCode).collect(Collectors.joining(",")))
159					.branchCompanyName(param.getBranchInfoDtoList().stream().map(IndicatorCusConfigModifyParam.BranchInfoDto::getBranchName).collect(Collectors.joining(",")))
160					.merchantName(param.getMerchantName())
161					.zhanqv(param.getZhanqv())
162					.qvyu(param.getQvyu())
163					.granularityType(param.getGranularityType())
164					.deliveryId(param.getDeliveryId())
165					.deliveryName(param.getDeliveryName())
166					.categoryId(param.getCategoryId())
167					.categoryName(param.getCategoryName())
168					.merchantId(param.getMerchantId())
169					.orderMode(param.getOrderMode())
170					.build();
171				this.indicatorCusConfigMapper.insertSelective(indicatorCusConfig);
172				// 保存配置关联的分公司
173				List<IndicatorBranchConfig> indicatorBranchConfigs = param.getBranchInfoDtoList().stream().map(branch -> IndicatorBranchConfig.builder()
174					.ictId(indicatorCusConfig.getId())
175					.branchCode(branch.getBranchCode())
176					.branchName(branch.getBranchName())
177					.build()).collect(Collectors.toList());
178				indicatorBranchConfigs.forEach(indicatorBranchConfig -> this.indicatorBranchConfigMapper.insertSelective(indicatorBranchConfig));
179				return Pair.of(indicatorCusConfig.getId(),"一城一策配置保存成功");
180			}
181			// 更新
182			IndicatorCusConfig indicatorCusConfig = indicatorCusConfigMapper.selectByPrimaryKey(param.getId());
183			IndicatorCusConfig snapshot = BeanCoverUtil.covert(indicatorCusConfig, new IndicatorCusConfig());
184	
185			Integer configType = param.getIndicatorUnitList().get(0).getConfigType();
186			Byte deliveryType = param.getIndicatorUnitList().get(0).getDeliveryType();
187			List<IndicatorUnit.IndicatorRule> indicatorRules = param.getIndicatorUnitList().get(0).getIndicatorRules();
188	
189			// 填充指标ID
190			for(IndicatorUnit.IndicatorRule indicatorRule : indicatorRules) {
191				List<String> names = indicatorRule.getIndicatorDateRules().stream().map(IndicatorUnit.IndicatorDateRule::getIndicatorName).collect(Collectors.toList());
192				List<IndicatorConfig> indicatorConfigs = new ArrayList<>();
193				if (CollectionUtil.isNotEmpty(names)){
194					indicatorConfigs = findIndicatorByNames(names);
195				}
196				Map<String, IndicatorConfig> nameIdMap = indicatorConfigs.stream().collect(Collectors.toMap(IndicatorConfig::getName, Function.identity()));
197				for (IndicatorUnit.IndicatorDateRule w : indicatorRule.getIndicatorDateRules()) {
198					w.setId(nameIdMap.get(w.getIndicatorName()).getId());
199					List<IndicatorBO.NodeConf> nodeConfs = JsonUtil.jsonStr2Obj(nameIdMap.get(w.getIndicatorName()).getContent(), new TypeReference<List<IndicatorBO.NodeConf>>() {});
200					nodeConfs.stream().filter(
201						nodeConf -> nodeConf.getHasMeasurementNode().equals(indicatorRule.getHasMeasurementNode())
202							&& nodeConf.getHasDeliveryNotificationNode().equals(indicatorRule.getHasDeliveryNotificationNode())
203							&& nodeConf.getDeliveryType().equals(deliveryType)
204					).findFirst().ifPresent(nodeConf -> {
205						w.setAssessmentRoles(nodeConf.getAssessmentRoles());
206						w.setVisibilityRoles(nodeConf.getVisibilityRoles());
207					});
208				}
209			}
210	
211			List<IndicatorUnit> list = Lists.newArrayList();
212			if(StringUtils.isNotEmpty(indicatorCusConfig.getContent())) {
213				list = JsonUtil.jsonStr2Obj(indicatorCusConfig.getContent(), new TypeReference<List<IndicatorUnit>>() {});
214			}
215			//  list 中存在相同的configType和deliveryType时，替换indicatorRules，否则新增IndicatorUnit
216			Optional<IndicatorUnit> optional = list.stream().filter(inu -> inu.getConfigType().equals(configType) && inu.getDeliveryType().equals(deliveryType)).findFirst();
217	
218			if (optional.isPresent()) {
219				// 如果找到了满足条件的元素，就更新它
220				optional.get().setIndicatorRules(indicatorRules);
221			} else {
222				// 如果没有找到满足条件的元素，就创建一个新的元素并添加到列表中
223				IndicatorUnit indicatorUnit = new IndicatorUnit();
224				indicatorUnit.setConfigType(configType);
225				indicatorUnit.setDeliveryType(deliveryType);
226				indicatorUnit.setIndicatorRules(indicatorRules);
227				list.add(indicatorUnit);
228			}
229	
230			indicatorCusConfig.setContent(JsonUtil.obj2JsonStr(list));
231			Long versionId = this.redoLogService.saveRedoLog(null, indicatorCusConfig);
232			indicatorCusConfig.setVersion(versionId.intValue());
233			this.indicatorCusConfigMapper.updateByPrimaryKeySelective(indicatorCusConfig);
234			// 保存历史记录
235			this.indicatorHistoryService.saveConfigHis(versionId,param.getIndicatorUnitList().get(0), snapshot);
236			return Pair.of(indicatorCusConfig.getId(),"");
237		}
