301		@Transactional
302		public Long createCusIndicatorConfig(CreateCusIndicatorParam param) {
303	
304			// 北京的特殊处理
305			// 北京的考核规则不受底线的限制, 视为自定义属性规则, isCus始终复制为true
306			if ("北京".equals(param.getQvyu()) && param.getCategoryComputeRule() != null && param.getCategoryComputeRule().getComputeRuleList() != null) {
307				for (CategoryComputeRule.ComputeRule computeRule : param.getCategoryComputeRule().getComputeRuleList()) {
308					for (TimeRule tr : computeRule.getFuncTimeRule().getTimeRuleList()) {
309						tr.setIsCus(true);
310					}
311				}
312			}
313	
314			if (param.getSourceId() == null) {
315				Validate.notEmpty(param.getQvyu());
316				List<DicBranchCompanyDto> dicBranchCompanyDtos = getBranchInfoByAreaName(param.getQvyu());
317				if (GranularityTypeEnum.LEVEL_2.getType().equals(param.getGranularityType())) {
318					// 配置区域维度时, 补充签约主体信息
319					List<BranchInfo> branches = dicBranchCompanyDtos.stream()
320							.map(w -> new BranchInfo(w.getBranchCompanyCode(), w.getBranchCompanyName()))
321							.collect(Collectors.toList());
322					param.setBranchInfoDtoList(branches);
323				}
324	
325				Validate.notEmpty(param.getBranchInfoDtoList());
326	
327				NIndicatorCusConfigExample example = new NIndicatorCusConfigExample();
328				example.createCriteria()
329						.andQvyuEqualTo(param.getQvyu())
330						.andIndicatorNameEqualTo(param.getIndicatorName())
331						.andSecondTypeEqualTo(param.getSecondType())
332						.andBusinessTypeEqualTo(param.getBusinessType())
333						.andBusinessVersionEqualTo(param.getBusinessVersion())
334						.andIsDeleteEqualTo((byte) 0);
335				List<NIndicatorCusConfig> nIndicatorCusConfigs = nIndicatorCusConfigMapper.selectByExample(example);
336	
337				// 同指标下,不同的配置颗粒度配置的值不能重复
338				validateCusDimDuplicate(nIndicatorCusConfigs, param);
339				NIndicatorCusConfig indicatorCusConfig = IndicatorConfigTransformer.param2NIndicatorCusConfig(param, commonService.getIndicatorNameConfig(""));
340				nIndicatorCusConfigMapper.insertSelective(indicatorCusConfig);
341	
342				// 保存配置关联的分公司
343				List<IndicatorBranchConfig> indicatorBranchConfigs = param.getBranchInfoDtoList().stream().map(branch -> IndicatorBranchConfig.builder()
344								.ictId(indicatorCusConfig.getId())
345								.branchCode(branch.getBranchCode())
346								.branchName(branch.getBranchName())
347								.build())
348						.collect(Collectors.toList());
349				indicatorBranchConfigs.forEach(indicatorBranchConfig -> indicatorBranchConfigMapper.insertSelective(indicatorBranchConfig));
350				return indicatorCusConfig.getId();
351			}
352	
353			if (param.getCategoryComputeRule() != null && param.getCategoryComputeRule().getDeliveryInfoList() == null) {
354				param.getCategoryComputeRule().setDeliveryInfoList(Collections.singletonList(ComplexQueryRpc.DEFAULT_DELIVERY_INFO));
355			}
356	
357			// 更新
358	
359			NIndicatorCusConfig indicatorCusConfig = nIndicatorCusConfigMapper.selectByPrimaryKey(param.getSourceId());
360			List<IndicatorComputeRule> indicatorComputeRules = IndicatorComputeRuleTransformer.param2IndicatorComputeRule(param, indicatorCusConfig);
361			IndicatorComputeRule rule = indicatorComputeRuleMapper.selectByPrimaryKey(param.getId());
362			// 更新场景下优先使用旧规则的供应商信息, 以正确更新版本
363			// 创建场景下使用param中的供应商信息
364			String deliveryInfo = rule != null ? rule.getDeliveryInfo() : indicatorComputeRules.get(0).getDeliveryInfo();
365			if (StringUtils.isNotEmpty(param.getHistoryStartTime()) && param.getHistoryVersion() != null) {
366				// 修改最新版本的考核规则
