378		/**
379		 * 判断区域维度指标维度配置是否重复
380		 * @param nIndicatorCusConfigs
381		 * @param param
382		 */
383		private void validateCusDimDuplicate(List<NIndicatorCusConfig> nIndicatorCusConfigs,CreateCusIndicatorParam param) {
384			// 获取不同维度下配置
385			Map<Integer, List<String>> dimKeyMap = getDimKey(nIndicatorCusConfigs);
386			// 当前配置
387			if (dimKeyMap.get(param.getGranularityType()) != null) {
388				// 当前维度已配置过
389				List<String> dimKeyList = dimKeyMap.get(param.getGranularityType());
390				// 判断同维度是否重复
391				if (param.getGranularityType().equals(GranularityTypeEnum.LEVEL_2.getType())) {
392					if (dimKeyList.contains(param.getQvyu())) {
393						throw new IllegalArgumentException("同指标下,区域" + param.getQvyu() + "已配置");
394					}
395				}
396				if (param.getGranularityType().equals(GranularityTypeEnum.LEVEL_3.getType())) {
397					param.getBranchInfoDtoList().forEach(e -> {
398						if (dimKeyList.stream().anyMatch(w -> w.contains(e.getBranchCode()))) {
399							throw new IllegalArgumentException("同指标下,区域分公司[" + e.getBranchName() + "]已配置");
400						}
401					});
402				}
403				if (param.getGranularityType().equals(GranularityTypeEnum.LEVEL_4.getType())) {
404					String dimKey = Joiner.on("-").join(param.getBranchInfoDtoList().get(0).getBranchCode(), param.getMerchantId(), param.getDeliveryId());
405					if (dimKeyList.contains(dimKey)) {
406						throw new IllegalArgumentException("同指标下,区域分公司[" + dimKey + "]已配置");
407					}
408				}
409			}
410		}
