412		public Map<Integer,List<String>> getDimKey(List<NIndicatorCusConfig> indicatorCusConfigs) {
413			return indicatorCusConfigs.stream().collect(Collectors.groupingBy(NIndicatorCusConfig::getGranularityType,
414				Collectors.mapping(e -> {
415					if (e.getGranularityType().equals(GranularityTypeEnum.LEVEL_2.getType())) {
416						return e.getQvyu();
417					}
418					if (e.getGranularityType().equals(GranularityTypeEnum.LEVEL_3.getType())) {
419						return e.getBranchCode();
420					}
421					if (e.getGranularityType().equals(GranularityTypeEnum.LEVEL_4.getType())) {
422						return Joiner.on("-").join(e.getBranchCode() ,e.getMerchantId() , e.getDeliveryId());
423					}
424					return "";
425				}, Collectors.toList())));
426		}
