156		public List<IndicatorOrderFulfillmentProgressPageDto> executorBuildFulfillmentDtoList(List<IndicatorOrder> indicatorOrders, IndicatorOrderFulfillmentProgressQueryParam param, Map<String, List<DispatchReceiveDto>> orderDispatchListMap) {
157			ExecutorService executor = Executors.newFixedThreadPool(10);
158			// 结果处理
159			int pageSize = calculatePageSize(indicatorOrders, 10);
160			int lastPage = calculateLastPage(indicatorOrders, pageSize);
161	
162			Map<LocalDateTime, Integer> calendars = holidayService.getRecentCalendar();
163	
164			List<CompletableFuture<List<IndicatorOrderFulfillmentProgressPageDto>>> futureList = IntStream.range(0, lastPage)
165					.mapToObj(i -> CompletableFuture.supplyAsync(() -> {
166						int fromIndex = i * pageSize;
167						int toIndex = Math.min((i + 1) * pageSize, indicatorOrders.size());
168						List<IndicatorOrder> subIndicatorOrders = indicatorOrders.subList(fromIndex, toIndex);
169						return buildOrderFulfillmentProgressDto(subIndicatorOrders, param, orderDispatchListMap, calendars);
170					}, executor))
171					.collect(Collectors.toList());
172	
173			List<IndicatorOrderFulfillmentProgressPageDto> resultList = futureList.stream()
174					.map(CompletableFuture::join)
175					.flatMap(Collection::stream)
176					.collect(Collectors.toList());
177	
178			executor.shutdown(); // 关闭线程池
179			try {
180				if (!executor.awaitTermination(60, TimeUnit.SECONDS)) {
181					executor.shutdownNow();
182				}
183			} catch (InterruptedException ex) {
184				executor.shutdownNow();
185				Thread.currentThread().interrupt();
186			}
187			return resultList;
188		}
