@Override
public ResultDTO<Long> indicatorBaseConfigCreateOrUpdate(IndicatorBaseConfigModifyParam param) {
    LOGGER.info("底线指标配置新建或者编辑，参数：{}", JsonUtil.obj2JsonStr(param));
    Pair<Long, String> retPair = indicatorEvalConfigWriteService.indicatorBaseConfigCreateOrUpdate(param);
    ResultDTO<Long> resultDTO = new ResultDTO<>(ResultCodeEnum.SUCCESS.getCode(),retPair.getRight());
    ReflectUtil.setFieldValue(resultDTO,"data",retPair.getLeft());
    return resultDTO;
}

@Override
public ResultDTO<Long> createBaseIndicator(CreateBaseIndicatorParam param) {
    LOGGER.info("底线指标配置新建或者编辑V2，参数：{}", JsonUtil.obj2JsonStr(param));
    if (param.getSourceId() != null) {
        ParamValidateUtils.validateCategoryComputeRule(param.getCategoryComputeRule());
    }
    Long id = indicatorEvalConfigWriteService.createBaseIndicatorConfig(param);
    ResultDTO<Long> resultDTO = new ResultDTO<>();
