Controller 入口有两个：V1 `indicatorBaseConfigCreateOrUpdate` 写 `n_indicator_base_config`（写 `content` 字段 + 版本号 + 历史记录）；V2 `createBaseIndicator` 写 `indicator_compute_rule` 表（品类规则 + 版本管理）。

**Service 写入链路（核心）：**

**文件：** `scm-workbench-service/src/main/java/com/ke/utopia/scm/workbench/service/write/IndicatorBaseConfigWriteService.java`
**类：** `IndicatorBaseConfigWriteService`
**方法：** `indicatorBaseConfigCreateOrUpdate` (第 85-160 行) / `createBaseIndicatorConfig` (第 163-199 行)

```java
// IndicatorBaseConfigWriteService.createBaseIndicatorConfig (第 163-199 行)
@Transactional
public Long createBaseIndicatorConfig(CreateBaseIndicatorParam param) {
    if (param.getSourceId() == null) {
        // 创建新的指标, 不去创建具体的品类规则
        NIndicatorBaseConfigExample example = new NIndicatorBaseConfigExample();
        example.createCriteria()
                .andIndicatorNameEqualTo(param.getIndicatorName())
                .andSecondTypeEqualTo(param.getSecondType())
                .andBusinessTypeEqualTo(param.getBusinessType())
                .andBusinessVersionEqualTo(param.getBusinessVersion())
                .andIsDeleteEqualTo((byte) 0);
        NIndicatorBaseConfig base = nIndicatorBaseConfigMapper.selectOneByExample(example);
        if (base != null) {
            return base.getId();
        }
        NIndicatorBaseConfig newConfig = IndicatorConfigTransformer.param2NIndicatorBaseConfig(
            param, commonService.getIndicatorNameConfig(""));
        indicatorConfigDao.insert(newConfig);
        return newConfig.getId();
    }
    // ... validate, 然后:
    List<IndicatorComputeRule> indicatorComputeRules =
        IndicatorComputeRuleTransformer.param2IndicatorComputeRule(param, baseConfig);
    if (StringUtils.isNotEmpty(param.getHistoryStartTime()) && param.getHistoryVersion() != null) {
        // 修改最新版本的考核规则
        indicatorComputeRuleService.updateIndicatorComputeRule(
            param.getHistoryVersion(), param.getHistoryStartTime(), null, indicatorComputeRules);
    } else {
        // 创建新版本的考核规则
        indicatorComputeRuleService.createIndicatorComputeRule(indicatorComputeRules, null);
    }
    // 刷新DAG
    indicatorDAGService.deleteCache();
    return param.getSourceId();
