// IndicatorComputeRuleService.diffOne (第 239-266 行)
public void diffOne(FuncTimeRule cusRule, FuncTimeRule baseRule) {
    Map<List<String>, TimeRule> baseRuleMap = baseRule.getTimeRuleList().stream()
        .collect(Collectors.toMap(TimeRule::getNodeFrom, Function.identity()));
    // 城市中自定义规则不参与对比
    Map<List<String>, TimeRule> cusRuleMap = cusRule.getTimeRuleList().stream()
            .filter(d -> !d.getIsCus())
            .collect(Collectors.toMap(TimeRule::getNodeFrom, Function.identity()));
    for (Map.Entry<List<String>, TimeRule> entry : cusRuleMap.entrySet()) {
        TimeRule cusTimeRule = entry.getValue();
        if (baseRuleMap.get(entry.getKey()) == null) continue;
        TimeRule baseTimeRule = baseRuleMap.get(entry.getKey());
        if (baseTimeRule.getTimeRef().equals("当天")) {
            Validate.isTrue(baseTimeRule.getTimeRef().equals(entry.getValue().getTimeRef()),
                "个性化时间关系要和底线时间关系一致");
            continue;
        }
        BigDecimal baseInterval = baseTimeRule.getInterval();
        Validate.isTrue(baseInterval.compareTo(cusInterval) >= 0,
            "个性化规则时间间隔要小于等于底线则时间间隔");
        Integer baseTimeType = baseTimeRule.getTimeType();
        if (HolidayService.CALENDAR_DAYS.equals(baseTimeType)) {
            Integer cusTimeType = cusTimeRule.getTimeType();
            Validate.isTrue(HolidayService.CALENDAR_DAYS.equals(cusTimeType),
                "底线规则是自然日时, 个性化规则也要使用自然日");
        }
    }
}
```

说明：个性化规则和底线规则逐条对比——时间间隔必须 `<=` 底线的间隔（第 258 行）；日历类型（自然日/工作日）必须一致（第 263 行）；时间关系（"当天"等）必须一致（第 254 行）。`isCus=true` 的自定义规则跳过校验。

