```java
// IndicatorComputeRuleService.createIndicatorComputeRule (第 122-172 行)
public void createIndicatorComputeRule(List<IndicatorComputeRule> newList, String originDeliveryInfo) {
    redoLogService.saveRedoLog(null, newList);
    Integer sourceType = newList.get(0).getSourceType();
    Long sourceId = newList.get(0).getSourceId();
    String categoryId = newList.get(0).getCategoryId();
    Date startTime = newList.get(0).getStartTime();
    Date endTime = new Date(startTime.getTime() - 1000);

    List<IndicatorComputeRule> indicatorComputeRules =
        bIndicatorComputeRuleMapper.getIndicatorComputeRuleBySourceId(sourceId, sourceType, categoryId, originDeliveryInfo);
    int newVersion = 0;
    Date oldStartTime = null;
    Map<String, String> oldMap = new HashMap<>();
    for (IndicatorComputeRule rule : indicatorComputeRules) {
        oldMap.put(getDimKey(rule), sourceType.equals(0) ? rule.getBaseComputeRuleNew() : rule.getCusComputeRuleNew());
        newVersion = Math.max(newVersion, rule.getVersion());
        if (oldStartTime == null || rule.getStartTime().compareTo(oldStartTime) > 0) {
            oldStartTime = rule.getStartTime();
        }
    }
    newVersion += 1;
    if (oldStartTime != null && startTime.compareTo(oldStartTime) <= 0) {
        throw new IllegalArgumentException("因存在生效时间更晚的考核版本，当前所选生效时间不可用，请调整生效时间。");
    }
    for (IndicatorComputeRule rule : indicatorComputeRules) {
        // 对于生效时间为正无穷的, 将end_time设置成传入的start_time - 1s
        if (IndicatorOrderServiceImpl.DEFAULT_END_TIME.equals(DateUtil.date2String(rule.getEndTime()))) {
            rule.setEndTime(endTime);
            rule.setMtime(null);
            indicatorComputeRuleMapper.updateByPrimaryKeySelective(rule);
            // 修改旧版本数据的操作日志
            IndicatorComputeRuleHistory indicatorComputeRuleHistory =
                IndicatorComputeRuleHistory.builder().endTime(endTime).build();
            IndicatorComputeRuleHistoryExample historyExample = new IndicatorComputeRuleHistoryExample();
            historyExample.createCriteria().andSourceIdEqualTo(rule.getSourceId())
                .andOriginIdEqualTo(rule.getId());
            indicatorComputeRuleHistoryMapper.updateByExampleSelective(indicatorComputeRuleHistory, historyExample);
        }
    }
    // 将传入的全部数据, 设置成最新的版本号, 插入数据库中
    insertData(sourceType, newList, newVersion, oldMap);
}
```

说明：版本管理关键逻辑——overlap 检测（第 146 行：新版本开始时间必须晚于现有最晚版本）、旧版本结束时间截断为 `newStartTime - 1s`、版本号自增、写 `indicator_compute_rule` + `indicator_compute_rule_history`（含新旧内容的 diff 描述）。

