    OrderSearchParam orderSearchParam = OrderSearchParam.builder().build();
    this.buildIndicatorOrderSearchParam(param, orderSearchParam); // 构建 ES 查询参数
    OrderSearchResult.Data data = new OrderSearchResult.Data();
    List<String> subOrderNoList;
    if ("test".equals(env) && StringUtils.isNotEmpty(param.getOrderNo())) {
        subOrderNoList = Collections.singletonList(param.getOrderNo());
        data.setTotal(1);
    } else {
        try {
            data = indicatorOrderEsSearchRpc.search(orderSearchParam,
                apolloConfig.getWorkBenchIndicatorEsSearchUrl(),
                apolloConfig.getWorkBenchIndicatorEsSearchToken());
        } catch (Exception e) {
            LOGGER.warn("订单指标履约进度查询失败,msg:{}", e.getMessage(), e);
        }
        if (CollectionUtil.isEmpty(data.getDocs())) {
            return new Page<>(...);
        }
        List<IndicatorOrderMappingEsDto> list = ListCovertUtil.covert(data.getDocs(),
            IndicatorOrderMappingEsDto.class);
        subOrderNoList = list.stream().map(IndicatorOrderMappingEsDto::getSubOrderNo)
            .collect(Collectors.toList());
    }
    // 根据 ES 返回的 orderNo 回查 MySQL
    IndicatorOrderExample ie = new IndicatorOrderExample().createCriteria()
        .andOrderNoIn(subOrderNoList).example();
    List<IndicatorOrder> indicatorOrders = indicatorOrderMapper.selectByExample(ie);
    Map<String, List<DispatchReceiveDto>> orderDispatchListMap =
        queryDispatchReceiveInfoByOrderNoList(subOrderNoList);
