// BizQueryIndicatorOrderController.queryOrderTime（第 49-92 行）
@Override
public ResultDTO<OrderTimeDto> queryOrderTime(BizQueryIndicatorOrderParam param) {
    LOGGER.info("queryOrderTime param:{}", JsonUtil.obj2JsonStr(param));
    ResultDTO<OrderTimeDto> resultDTO = new ResultDTO<>();
    OrderTimeDto orderTimeDto = new OrderTimeDto();
    orderTimeDto.setProjectOrderId(param.getProjectOrderId());

    List<IndicatorOrder> indicatorOrders = indicatorOrderDao
        .queryByProjectOrderIdAndCategoryIdAndSupplierId(
            param.getProjectOrderId(), param.getCategoryId(),
            param.getSupplierId(), param.getOrderNos());
    if (CollectionUtils.isEmpty(indicatorOrders)) {
        orderTimeDto.setOrderFlowNodeTimes(Lists.newArrayList());
        resultDTO.success(orderTimeDto); return resultDTO;
    }
    List<OrderTimeDto.OrderFlowNodeTime> orderFlowNodeTimes = new ArrayList<>();
    indicatorOrders.forEach(order -> {
        OrderTimeDto.OrderFlowNodeTime orderFlowNodeTime = new OrderTimeDto.OrderFlowNodeTime();
        List<OrderTimeDto.NodeTime> nodeTimes = Lists.newArrayList();
        List<DispatchReceiveDto> dispatchReceiveDtos =
            ofcRpc.queryDispatchReceiveByMainFlowNo(order.getOrderNo());
        SubOrderComplexDto subOrderComplexDto =
            subOrderQueryManager.querySubOrderBaseInfo(order.getOrderNo());
        // 实际完成时间
        Map<Integer, List<DispatchReceiveDto>> dispatchMap =
            Optional.ofNullable(dispatchReceiveDtos).orElse(new ArrayList<>()).stream()
                .filter(d -> d.getOperationTime().compareTo(
                    DateUtil.parse("2000-01-01",DateUtil.DATE_FMT_3)) > 0)
                .collect(Collectors.groupingBy(DispatchReceiveDto::getActionType));
        // 期望完成时间
        Map<String, Long> expectTime = this.getExpectTime(param.getNodeIds(), order);
        param.getNodeIds().forEach(w -> {
            OrderTimeDto.NodeTime nodeTime = new OrderTimeDto.NodeTime();
            nodeTime.setNodeId(w);
            nodeTime.setCompleteTimes(
                dispatchMap.getOrDefault(Integer.valueOf(w), new ArrayList<>()).stream()
                    .map(o -> o.getOperationTime().getTime()).collect(Collectors.toList()));
            nodeTime.setPlanCompleteTime(expectTime.getOrDefault(w, 0L));
            nodeTimes.add(nodeTime);
        });
        orderFlowNodeTime.setPlanArrivedTime(
            subOrderComplexDto.getPlanArrivedTime() != null
                ? subOrderComplexDto.getPlanArrivedTime().getTime() : 0L);
        orderFlowNodeTime.setOrderNo(order.getOrderNo());
        orderFlowNodeTime.setNodeTimes(nodeTimes);
        orderFlowNodeTimes.add(orderFlowNodeTime);
    });
    orderTimeDto.setOrderFlowNodeTimes(orderFlowNodeTimes);
    resultDTO.success(orderTimeDto);
    return resultDTO;
}
```

说明：给业务方查询考核时间——从 `indicator_order` 查出订单，关联 OFC 配送行程获取实际完成时间 (`DispatchReceiveDto`)，从考核结果的 `baseEvalResultNew`/`cusEvalResultNew` JSON 解析出期望完成时间，组装为 `OrderTimeDto` 返回。

