    List<ScheduleIndicatorDto> res = new ArrayList<>();
    List<Long> nodeIds = param.getNodeIds();
    if (nodeIds != null && !nodeIds.isEmpty()) {
        // 根据nodeId, 获取用工任务(设计, 测量, 复尺)的考核信息
        IndicatorTaskDispatchNodeExample nodeExample = new IndicatorTaskDispatchNodeExample();
        nodeExample.createCriteria().andNodeIdIn(nodeIds).andIsDeleteEqualTo((byte) 0);
        if (StringUtils.isNotBlank(param.getProjectOrderId())) {
            nodeCriteria.andProjectOrderIdEqualTo(param.getProjectOrderId());
        }
        List<IndicatorTaskDispatchNode> dispatchNodes =
            indicatorTaskDispatchNodeMapper.selectByExample(nodeExample);
        for (IndicatorTaskDispatchNode node : dispatchNodes) {
            res.add(ScheduleIndicatorDto.builder()
                .projectOrderId(node.getProjectOrderId()).orderNo(node.getOrderNo())
                .categoryId(node.getCategoryId()).supplierId(node.getSupplierId())
                .taskType(node.getTaskType()).nodeType(node.getNodeType())
                .nodeId(node.getNodeId())
                .assessmentStartTime(DateUtil.date2String(node.getAssessmentStartTime()))
                .assessmentEndTime(DateUtil.date2String(node.getAssessmentEndTime())).build());
        }
    }
    List<String> orderNos = param.getOrderNos();
    if (orderNos != null && !orderNos.isEmpty()) {
        // 根据货单号, 获取用工任务(安装)的考核信息
        IndicatorTaskDispatchNodeExample nodeExample = ...;
        List<IndicatorTaskDispatchNode> dispatchNodes = ...;   // 同上模式
        // 根据货单号, 获取货单任务的考核信息
        FulfillmentTaskExample taskExample = new FulfillmentTaskExample();
        taskExample.createCriteria().andRelateSubOrderNoIn(orderNos)
            .andAssessmentStartTimeGreaterThan(ConstructionScheduleService.defaultDate)
            .andIsDeleteEqualTo((byte) 0);
        List<FulfillmentTask> fulfillmentTasks =
            fulfillmentTaskMapper.selectByExample(taskExample);
        for (FulfillmentTask task : fulfillmentTasks) {
            if (SyncMaterialTaskService.fulfillmentTaskToMaterialTaskType
                    .containsKey(task.getTaskType())) {
                List<Integer> typeInfo = SyncMaterialTaskService
                    .fulfillmentTaskToMaterialTaskType.get(task.getTaskType());
                res.add(ScheduleIndicatorDto.builder()
                    .projectOrderId(task.getProjectCode()).orderNo(task.getRelateSubOrderNo())
                    .categoryId(task.getCategoryId()).supplierId(task.getDeliveryId())
                    .taskType(typeInfo.get(0)).nodeType(typeInfo.get(1)).nodeId(0L)
                    .assessmentStartTime(DateUtil.date2String(task.getAssessmentStartTime()))
                    .assessmentEndTime(DateUtil.date2String(task.getAssessmentEndTime())).build());
            }
        }
    }
    return res;
}
```

说明：排程考核结果查询——分两路：`nodeIds` 查到 `indicator_task_dispatch_node`（设计/测量/复尺等用工任务的考核起止时间），`orderNos` 查到 `indicator_task_dispatch_node`（安装）+ `fulfillment_task`（货单任务的考核起止时间），统一组装为 `ScheduleIndicatorDto` 列表返回。

